programs.sol:
"""A syntax-opener response, rather than a general dollar-sign detector.

Predict negative values for dollar/LaTeX openers at new lines or after another
formula, with weaker responses to variables in code and to inline delimiters.
Also recognize URL schemes, especially HTTPS's separator, and JSON object
openers and hexadecimal byte escapes. Everything else is zero. The last
96 characters are remembered;
attention/document resets clear that history. Constants are training means.
"""
import re

READS = ()


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    tail = '' if carry is None or carry[0] != doc else carry[1]
    s = prefix.token_strings[-1]
    value = response(s, tail)
    return (doc, (tail + s)[-96:]), value


def response(s, tail):
    t = s.strip()
    # Indentation, Markdown quotations, and list bullets may precede a formula.
    new_line = bool(re.search(
        r'\n[ \t]*(?:>[ \t]*|(?:\d+[.)]|[-*])[ \t]+)?$', tail))
    after_formula = tail.rstrip().endswith('$')
    if t == '://':
        return -1.06 if tail.endswith('https') else -0.11
    if t in ('http', 'https'):
        return -1.40 if new_line or tail.endswith('[') else 0.08
    if s == '{"':
        return -0.46 if new_line else -0.22
    if '\n' in s:
        return 0.0
    if t in (r'\(', r'\['):
        return (-3.32 if t == r'\(' else -1.74) if new_line else -0.04
    if t == r'\x':
        return -1.06 if tail.endswith(r'\n') else 0.23
    if t == '\\' and new_line:
        return -0.30
    if t.startswith('(\\') and tail.endswith('\\'):
        return -1.20  # a LaTeX opener split across tokens
    if t.startswith(r'\$'):
        return -1.11 if new_line else 0.0
    if t.startswith('$'):
        # Multi-letter identifiers and jQuery member access are not formulas.
        if re.match(r'\$[A-Za-z_][A-Za-z_0-9]{1,}', t) or t.startswith('$.'):
            return 0.0
        if t.startswith('$('):
            return -1.44 if new_line and t == '$(' else 0.0
        if t.startswith('$$'):
            if new_line:
                return -2.47
            return -1.21 if after_formula else 0.11
        if t.startswith('${'):
            return -3.61 if new_line else -0.08
        if new_line:
            if len(t) > 1:
                return -3.21
            code = any(mark in tail for mark in
                       ('->', ';', '<?php', 'function ', 'return ', '= $'))
            if code:
                return -1.27 if s.startswith(' ') else -1.00
            return -2.88 if s.startswith(' ') else -2.61
        if s.startswith(' '):
            if after_formula:
                return -2.22
            return -1.03 if tail[-1:].isspace() else -0.21
        return -0.04
    if '$' in t and t[0] in '([{=/' and t.endswith('$'):
        return -0.28
    return 0.0

programs.haiku:
"""Layer-1 MLP down_proj component 1280: a LaTeX-math and markup-opener detector.

It goes negative on the token that opens a LaTeX math span. The strongest case
is display math, an opener that starts a line ("$", "$$", "$\\", "${", "\\(",
"\\[" right after a newline). Inline openers are weaker: after indentation
(~-1.1) or punctuation such as "=", "," or ":" (~-0.5), and near 0 right after
a word, as in prose money ("of $5"). Line-initial web links ("http", "https")
and code fences ("`") are also negative, as are the "://" of an http(s) URL and
the '{"' that opens a JSON tool call on its own line. Runs of middle dots
("··········", leader dots) are mildly positive. Everywhere else it is 0.
"""

READS = ()

LINE_OPENERS = {"http": -1.8, "https": -1.8, " http": -1.8, " https": -1.8, "`": -1.1, " `": -1.1}


def is_math_opener(text):
    return "$" in text or text in ("\\(", "\\[")


def step(carry, prefix, upstream):
    text = prefix.token_strings[-1]
    if len(prefix.token_ids) < 2 or prefix.document_ids[-2] != prefix.document_ids[-1]:
        prev = ""
    else:
        prev = prefix.token_strings[-2]
    line_start = "\n" in prev
    value = 0.0
    if is_math_opener(text):
        if line_start:
            value = -3.9 if text.startswith("$\\") else -2.4
        elif prev and prev.strip() == "":
            value = -1.1
        elif prev[-1:].isalpha():
            value = -0.1
        else:
            value = -0.5
    elif line_start and text in LINE_OPENERS:
        value = LINE_OPENERS[text]
    elif text == "://" and prev.strip() in ("http", "https"):
        value = -0.66
    elif text == '{"' and line_start:
        value = -0.46
    elif text and set(text) == {"·"}:
        value = 0.75
    return carry, float(value)

programs.sol:
"""Approximate a response to the later pieces of unfamiliar, name-like words.

Short lowercase continuations of a capitalized stem containing a Latin vowel get
large positive values. More fragmented stems strengthen this response;
long pieces, long stems and common English words weaken it. There are smaller
responses for uncapitalized continuations and for new contexts (rows/documents).
"""
import re
from functools import lru_cache
from wordfreq import zipf_frequency

READS = ()
LANGUAGES = ('en', 'de', 'fr', 'es', 'pt', 'it', 'nl', 'ru')


@lru_cache(maxsize=50000)
def frequencies(word):
    values = [zipf_frequency(word, language) for language in LANGUAGES]
    return values[0], max(values)


def has_vowel(text):
    # A deliberately simple Latin spelling cue, including y.
    return any(c in 'aeiouy' for c in text.lower())


def response(stem, piece, parts):
    if not has_vowel(stem):
        if frequencies(stem)[1] > 4.875:
            return -0.013
        return 0.100 if stem[0].isupper() else 0.018

    if not stem.istitle():
        if not has_vowel(piece):
            return -0.003
        if len(piece) > 3:
            return 0.029
        if parts == 1:
            return 0.079
        return 0.224 if len(stem) <= 4 else 0.113

    if not piece.islower():
        return 0.014
    english, common = frequencies(stem + piece)
    if common > 3.625:
        if english > 3.625:
            return 0.033
        return 0.268 if english > 2.125 else 0.089
    if not has_vowel(piece):
        return 0.114
    if len(piece) > 4:
        return 0.126
    if len(stem) > 6:
        return 0.218
    if parts > 1:
        return 0.465
    return 0.158 if frequencies(stem)[1] > 6.875 else 0.351


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    initial = carry is None or carry[0] != doc
    stem, parts = ('', 0) if initial else carry[1:]
    token = prefix.token_strings[-1]
    head = re.match(r'[^\W\d_]+', token)
    value = 0.097 if initial else -0.002
    if stem and head:
        value = response(stem, head[0], parts)

    tail = re.search(r'[^\W\d_]+$', token)
    if tail is None:
        word, count = '', 0
    elif tail.start() == 0:
        word, count = (stem + tail[0])[-80:], parts + 1
    else:
        word, count = tail[0], 1
    return (doc, word, count), value

"""Approximate the component's initial-token formatting response.

The large responses occur before a document has acquired varied context.
File-path fragments and escapes give negative responses; indentation,
member names and several kinds of code give positive ones. Ordinary text
has much smaller, mostly negative initial biases. Once the token changes,
return zero. Document boundaries restart this rule. Keeping the response
across an identical-token run also covers repetitive padding and markers.
These category rules omit fine lexical differences and the small later
context-dependent activations; they do not reconstruct the whole component.
"""
from functools import lru_cache

READS = ()

# Suffixes used as domains and as source-file extensions, not member names.
DOMAINS = set('com org net edu gov mil io'.split())
SOURCE_EXTENSIONS = set(
    'c h cc cpp hpp py js ts jsx tsx go rs rb php java cs md txt sh git'.split()
)
DIRECTORIES = set(
    'src lib bin etc home tmp test tests docs assets resources packages '
    'dist vendor modules'.split()
)
RESOURCE_DIRECTORIES = set('modules packages assets resources images'.split())
ARTICLES = set('a an the'.split())
COPULAS = set('am is are was were be been being'.split())
HAVE = set('has have had'.split())
PREPOSITIONS = set(
    'of at to by without into over under above through across per than'.split()
)
PRONOUNS = set('you it they them we us'.split())


@lru_cache(maxsize=8192)
def initial(s):
    w = s.strip()
    if s.isspace():
        if '\xa0' in s or '\f' in s:
            return -2.0
        if '\r' in s:
            return -1.1
        if '\n' in s:
            return -0.2
        n = s.count(' ')
        if n == 0:
            return 0.3
        if n == 1:
            return 0.7 if '\t' in s else -0.56
        if n == 2:
            return 0.5
        value = 2.5 - 0.075 * n + (1.0 if n % 4 == 3 else 0.0)
        if '\t' in s:
            value -= 0.6 + 0.06 * n
        return max(-4.0, value)

    if s == '<|im_start|>':
        return 0.13
    if s == '<|endoftext|>':
        return -2.0
    if len(w) > 1 and len(set(w)) == 1:
        if w[0] == '^':
            return -6.2
        if w[0] == '·':
            return -8.9
    if '\x00' in s:
        return -7.4
    if s.startswith('/'):
        if len(s) > 1 and s[1].isascii() and s[1].isalpha():
            return -8.0 if len(s) <= 3 else -14.0
        if s == '/':
            return -4.0
        if s == '/\n':
            return -8.9
        if s.startswith('/*'):
            return 0.1
        if s.startswith('//'):
            return -2.9 if '\n' in s else -1.0
    if s.startswith('-') and s[1:].isascii() and s[1:].isalpha():
        if s[1].isupper():
            return -1.6
        return -4.6 if len(s) == 2 else -7.0
    if s.startswith('.') and s[1:].isascii() and s[1:].isalpha():
        name = s[1:]
        if name in DOMAINS:
            return -10.0
        if name in SOURCE_EXTENSIONS:
            return -3.2
        return 2.7
    if s.startswith('_') and s[1:].isascii() and s[1:].isalpha():
        if s[1:] in RESOURCE_DIRECTORIES:
            return -5.0
        return 1.8
    if s == '\\"':
        return -13.3
    if '\\"' in s:
        return -5.0
    if s == '\\t':
        return -6.2
    if len(s) >= 4 and set(s) == {'\\'}:
        return -9.0
    if s == ';' or s == '`':
        return -2.8
    if w.startswith('"') and w.endswith((':', ',')):
        return 2.0
    if w.startswith('"""'):
        return 2.6
    if s.startswith('#include'):
        return 2.9
    if s.startswith('<?'):
        return 2.4

    # Lowercase programming syntax, distinguished from title-case prose.
    if w in DIRECTORIES:
        if s == w:
            return -8.0 if w.endswith('s') else -5.5
        return -2.5
    if w == 'path' and s == w:
        return -5.0
    if w in {'print', 'printf', 'cout', 'console'}:
        return 6.0
    if w in {'public', 'private'}:
        return 4.8 if s.startswith(' ') else 8.8
    if w in {'protected', 'internal'}:
        return 2.6
    if w == 'new':
        return 4.0
    if w in {'if', 'while', 'for', 'foreach'}:
        if s.startswith('\t'):
            return 5.7
        if s.startswith(' '):
            return 0.6 if w == 'for' else 2.8
        return 4.3
    if w in {'return', 'throw', 'catch'}:
        return 5.5 if s.startswith('\t') else 3.5
    if w in {'use', 'export', 'require'} and s == w:
        return 5.0
    if w in {'using', 'include'} and s == w:
        return 3.0
    if w in {'def', 'function', 'namespace', 'let'}:
        return 2.0
    if w in {'var', 'const', 'static'}:
        return 0.25 if s == w else 1.8
    if w in {'string', 'array'}:
        return -5.5 if s == w else 1.8
    if w in {'str', 'len', 'dict'}:
        return 4.7
    if w in {'int', 'void', 'bool'}:
        return -1.8 if s == w else 1.8
    if w == '=':
        return 0.4 if s == w else 2.1

    if len(w) == 1 and w.isascii() and w.isdigit():
        # The largest digit has a notably stronger initial response.
        return 2.0 if w == '9' else -0.2 + 0.10 * int(w)
    low = w.lower()
    if low in ARTICLES:
        return -0.25 if w.istitle() else -0.6
    if low in COPULAS:
        return -0.7
    if low in HAVE:
        return -1.2
    if low in PREPOSITIONS:
        return -0.65
    if low in PRONOUNS:
        return -0.35 if w.istitle() else -0.65
    if len(w) == 1 and w.isascii() and w.isupper():
        return -0.6
    if w.isalpha():
        return -0.08
    return -0.2


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_bytes[-1]
    if carry is None or doc != carry[0]:
        value = initial(prefix.token_strings[-1])
        return (doc, token, True, value), value
    _, first, unchanged, value = carry
    unchanged = unchanged and token == first
    return (doc, first, unchanged, value), value if unchanged else 0.0

"""Case and word-boundary response.

Predict negative values for lowercase starts after sentence punctuation, newlines,
quotes and brackets; longer quoted words get a larger response. These are often
places where capitalization or a new lexical item is expected. Document openings
get a positive offset. Preserve two strong formatting responses: the colon in an
initial 'Title:' label and tokens consisting of repeated middle dots.
"""
import re

READS = ()
ABBREVIATIONS = set('''mr mrs ms dr prof sr jr st vs etc fig figs eq eqs
ref refs cf al vol vols pp p ch sec no e g i ie eg inc ltd co corp rev
 gen col capt lt dept approx misc ed eds ca'''.split())


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        pos, prev, tail = 0, '', ''
    else:
        _, pos, prev, tail = carry
    s = prefix.token_strings[-1]
    w = s.strip()
    word = w.lstrip('._([\'"')
    lower, upper = word[:1].islower(), word[:1].isupper()
    leading = s[:1].isspace()
    size = min(len(word), 6)
    p = prev.rstrip()
    value = 0.02 * upper + 0.02 * w.isupper()
    if s.startswith('<'):
        value += 0.04
    if pos == 0:
        value += 0.40 + 0.08 * lower + 0.17 * upper
    if pos == 1 and s == ':' and prev == 'Title':
        value -= 12.0
    if len(w) > 1 and set(w) == {'·'}:
        value += 1.9

    if lower:
        value -= 0.03
        if not leading and prev.endswith((' ', '\t')):
            value += 0.05 - 0.035 * size
        if not leading and prev.endswith('\n'):
            value -= 0.33
        if not leading and p.endswith(('"', "'", '`')):
            value -= 0.08 * size
        if p.endswith(('(', '[', '{')):
            value -= 0.15
        if w.startswith(('(', '[')):
            value -= 0.08
        if p.endswith(':'):
            value -= 0.25
        if p.endswith('.'):
            value -= 0.30
        if p.endswith(('?', '!')):
            value -= 0.32
        if re.search(r'[.!?]["\'’”)]*\s+$', tail):
            value -= 0.16 + 0.07 * size

        # A prose ending, rather than a dotted identifier or abbreviation.
        text = tail.rstrip()
        line = text.rsplit('\n', 1)[-1]
        code = (any(c in line for c in '{}=;') or '->' in line
                or line.count('(') > 1 or line.startswith(('    ', '\t')))
        match = re.search(r'(\w+)\.["\'’”)]*$', text)
        abbreviated = bool(match and (
            match[1].lower() in ABBREVIATIONS or len(match[1]) == 1
            or (match[1].isupper() and len(match[1]) < 5)))
        if (leading or tail[-1:].isspace()) and not code and not abbreviated:
            if re.search(r'(?<!\.)[.!?]["\'’”)]*$', text):
                value -= 0.70 + 0.05 * size - 0.30 * (not leading)
        if prev.endswith('\n') and not code:
            value -= 0.12
            if '\n\n' in prev:
                value -= 0.12
        if re.search(r'<\|im_start\|>(user|assistant)\s*$', tail):
            value -= 0.90
    return (doc, pos + 1, s, (tail + s)[-250:]), float(value)

"""Starts of enumerations in code, with a few related TeX delimiters.

The main positives are named imports, multiline argument lists, and data
objects. Ordinary function/condition blocks are weak or negative. Real and
literal escaped line breaks are distinguished; other tokens are quiet.
Only the last 400 characters of the current document are retained.
"""
import re

READS = ()


def predict(token, before):
    s = token.lstrip(' \t')
    if not any(c in s for c in '{([<\\') and s not in ('import', '::'):
        return 0.0
    raw = before
    # TeX math groups and f-string fields are not code data objects.
    tex = re.search(r'\\(?:left|right|frac|math\w*|boxed|newcommand|vec|begin)\b', raw)
    if s == '{\\' and tex:
        return 0.1 if not token.startswith(' ') else 0.25
    quotes = re.sub(r'\\+([\"\'])', r'\1', raw)
    fstring = re.search(r'''\bf[r]?(?:"[^"]*|'[^']*)$''', quotes)
    if s == '{' and fstring:
        return -0.15
    before = before.replace('\\n', '\n').replace('\\t', '\t')
    before = re.sub(r'(?m)^\s*\d+\t', '', before)
    before = re.sub(r'(?m)^\s*//[^\n]*', '', before)
    b = before.rstrip()
    line = before.rsplit('\n', 1)[-1]
    importing = bool(re.search(r'\bimport(?:\s+type)?(?:\s+\w+,)?$', b))
    if s == 'import':
        return 2.0 if re.search(r'\bfrom\s+[\w.]+\s*$', line) else 0.0
    if s == '::':
        use_path = re.search(r'(?:^|[;{}])\s*(?:pub\s+)?use\s+[\w:]+$', line)
        return 0.7 if use_path else 0.0
    if s == '::{':
        return 1.85
    # Compact JSON object nesting, and consecutive records.
    if re.fullmatch(r'"?:\[?\{"', s):
        return 0.65
    if re.fullmatch(r'"?\},\{"', s):
        return 1.0
    if s == '},{':
        return 0.35
    if s in ('_{', '}_{', '^{'):
        return -0.09
    if token == '\\':
        if raw.endswith(('_{', '^{')):
            return 0.03
        if raw.endswith('{'):
            return 0.7
        if raw.endswith('(') and re.search(r'[\w.]\($', raw):
            return 1.3 if not raw.endswith(('left(', 'right(')) else 0.05
        return 0.0
    if re.fullmatch(r'(?:[>!]?[(\[]|<)[\r\n]+', s):
        if raw.endswith('\\'):
            return 0.08
        if importing:
            return 2.4
        return 1.25 if '(' in s else 0.85 if '<' in s else 1.0
    if re.fullmatch(r'[(\[]\\', s):
        if importing:
            return 1.6
        if '[' in s:
            return 1.0 if token.startswith(' ') else 0.1
        code_continuation = '\\n' in raw and re.search(r'[\w=]$', b)
        return 0.4 if code_continuation and not b.endswith(('left', 'right')) else 0.07
    if s.startswith('{\"'):
        return 0.9 if b.endswith((',', '[')) else 0.1 if token.startswith(' ') else 0.0
    if re.fullmatch(r'(?:\}|\{|\$)\{[\r\n]+', s):
        return 0.9
    # Separate data objects from ordinary function/condition blocks.
    if re.fullmatch(r'(?:\{|\(\{|\[\{|[>=]\{|]=\{)[\r\n]*\\?', s):
        multiline = '\n' in s
        escaped = s.endswith('\\')
        crlf = 1.1 if '\r\n' in s else 0.0
        if importing:
            return 2.1
        if re.search(r'(?:^|[:;{}])\s*(?:export\s+)?(?:const|let|var)$', line):
            return 1.9
        if re.search(r'(?:\bexport(?:\s+type)?|&)\s*$', b):
            return 0.9
        if s.startswith(('({', '[{', '={', ']={')):
            if multiline or escaped:
                return 1.3
            return 1.0 if s.startswith('[{') else 0.1 if s.startswith('={') else 0.6
        if multiline or escaped:
            if b.endswith(('=', ':', '[', '(', ',', 'return')):
                return (1.6 if escaped else 1.4) + crlf
            if b.endswith(')'):
                return 0.34 if escaped else -0.10
            if b.endswith(('=>', 'else')):
                return 0.7 if escaped else 0.25
            if not token.startswith(' ') and s.startswith('{') and multiline:
                return 0.8 if '\n\n' in s else 0.45
            if escaped and not token.startswith(' ') and '\\n' in raw:
                return 0.8
            return 0.6 if escaped and token.startswith(' ') else 0.1
        if b.endswith(')'):
            return -0.25
        if b.endswith((',', '[')) or (b.endswith('{') and not line.strip()):
            return 0.85
        if b.endswith((':', '=')):
            unescaped = re.sub(r'\\.', '', line)
            in_string = unescaped.count(chr(34)) % 2 or unescaped.count(chr(39)) % 2
            if in_string:
                return -0.15
            return 0.65 if b.endswith(':') else 0.15
        return 0.03
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    before = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    return (doc, (before + token)[-400:]), predict(token, before)

programs.haiku:
"""Import-list and literal-opening detector for layers.1.mlp.down_proj:1284.

The component fires on the tokens where the code is opening a list of names or a
data literal:
  * the word `import` in a from/import statement (strongest),
  * an opening `{`, `(` or `[` right after `import`, `const`, `let`, `var` or `export`
    (destructuring and import lists),
  * a line-ending opener `(`, `[`, `{` (e.g. `foo(` then newline) and a line-ending `{`
    after `:`, `=`, `,` (object or array literals),
and it is slightly negative on `{` that opens a block after `)` (if/for/function headers).
Everything else is 0. Carry = (current line text, previous token, document id).
"""

import re

READS = ()
OPENER = re.compile(r"\s*[(\[{]+\s*\\?\s*\n?")
LIST_WORDS = re.compile(r"\b(import|export|const|let|var)\s*$")


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    tok = prefix.token_strings[-1]
    if carry is None or carry[2] != doc:
        line, prev = "", ""
    else:
        line, prev = carry[0], carry[1]
    before = line.rstrip()
    newline = "\n" in tok
    if tok.strip() == "import" and tok.startswith(" "):
        value = 2.1 if line.lstrip().startswith("from") else 0.9
    elif OPENER.fullmatch(tok) and ("{" in tok or newline):
        if prev.strip() == "import" or LIST_WORDS.search(before):
            value = 1.9
        elif before[-1:] == ")":
            value = -0.2
        elif newline and "{" not in tok:
            value = 1.0
        elif newline and before[-1:] in (":", "=", ","):
            value = 1.5
        elif before[-1:] == ",":
            value = 0.6
        else:
            value = 0.2
    else:
        value = 0.0
    if newline or "<|endoftext|>" in tok:
        line = tok.split("\n")[-1]
        if "<|endoftext|>" in line:
            line = ""
    else:
        line = (line + tok)[-200:]
    return (line, tok, doc), float(value)

programs.sol:
"""Approximate local punctuation and code-boundary responses.

Large positive values mark Romance-language elisions, shell options and root
paths, control parentheses, declarations, imports and LaTeX labels/row ends.
Numeric ratios, fused internal path segments and ordinary text are usually quiet.
Nonzero levels are rounded training means for these contexts, except the
quoted-root value, taken from the observed quoted-slash token mean.
Keep only 200 trailing decoded characters, resetting for each document.
"""
import re
import regex

READS = ()
CONTROL = {
    'if', 'while', 'for', 'switch', 'catch', 'foreach', 'with', 'elif', 'using',
}
MODIFIERS = {'public', 'private', 'protected', 'static'}
# Ordinary declaration, then declaration following a closed block or annotation.
DECLARATION_LEVELS = {
    'public': (0.61, 0.91),
    'private': (0.31, 0.75),
    'protected': (0.69, 1.05),
    'static': (1.05, 0.7),
}

COMMANDS = {
    'cat', 'grep', 'head', 'tail', 'git', 'find', 'ls', 'sed', 'rg',
    'diff', 'curl', 'python', 'pytest', 'cargo', 'npm', 'npx', 'pip',
    'sort', 'cut', 'wc', 'xargs', 'chmod', 'rm', 'cp', 'mv', 'mkdir',
    'echo', 'docker', 'node', 'cd',
}
SHELL = re.compile(r'\b(?:' + '|'.join(sorted(COMMANDS)) + r')\b')
ELISION_PREFIXES = {
    'l', 'd', 'qu', 'dell', 'all', 'nell', 'dall', 'sull', 'coll', 'un',
}


def response(s, tail):
    q = s.strip()
    if s == '{' and tail.endswith('\\label'):
        return 1.23
    if s == ':' and re.search(r'\\(?:label|ref|eqref)\{[^{}:]*$', tail):
        return 0.77
    if s == 'label' and tail.endswith('\\'):
        return 0.84
    if s in {'h', 'line'} and (tail.endswith('\\') and s == 'h'
                               or tail.endswith('\\h') and s == 'line'):
        return 0.42
    if q in {'://', ':///'}:
        return -0.07 if q == '://' else 0.88
    if not (q in MODIFIERS or q in {'-', '--', "'", '’', ':', '{', 'import'}
            or '/' in s or '／' in s or '\\' in s or s.startswith((' (', '::'))
            or q in {'|', '&&', '·', '··', '・', '•'}):
        return 0
    word_match = re.search(r'(\w+)$', tail)
    word = word_match[1] if word_match else ''
    line = tail.replace('\\n', '\n').rsplit('\n', 1)[-1]
    if s in (' -', ' --'):
        if word in COMMANDS:
            return 1.59
        if SHELL.search(line):
            return 0.91
        return 0.05
    if s == '-':
        if tail and regex.fullmatch(r'\p{Script=Cyrillic}', tail[-1]):
            return 0.71
        return 0.17 if word and not word.isdigit() else 0
    if s in ("'", '’'):
        if word in ELISION_PREFIXES:
            return 0.89
        if word in {'j', 't', 'm', 'n', 'c', 's'}:
            return 0.28
        if word.lower() in ELISION_PREFIXES:
            return 0.39
        return 0
    if s.startswith(' ('):
        if word in CONTROL:
            return 0.65
        if word in {'function', 'import'}:
            return 0.38
        return 0
    if s.startswith('::'):
        if re.search(r'\buse\s+[^;]*$', line):
            return 1.3
        return -0.17 if tail.endswith('.py') else 0.24
    if q in MODIFIERS:
        indented = not line.strip() or s.startswith('\t')
        code = (indented or word in MODIFIERS
                or word in {'final', 'abstract', 'inline', 'extern'})
        if not code:
            return 0
        after_block = tail.rstrip().endswith('}') or re.search(r'@\w+\s*$', tail)
        ordinary, after = DECLARATION_LEVELS[q]
        return after if after_block else ordinary
    if s == ' import':
        return 1.34 if re.search(r'\bfrom\s+', line) else -0.13
    if s == 'import':
        return -0.1
    if q == '／':
        return 0.1
    if q.startswith('/') and not q.startswith('//'):
        if word.isdigit() or (tail and tail[-1] in ')]}'):
            return 0
        if s[:1].isspace():
            return 0.97 if word in COMMANDS else 0.4
        run = tail.rsplit(None, 1)[-1] if tail.split() else ''
        if s == '/':
            return 0.22 if word else 0.26
        if '/' in run:
            return 0
        return 0.35 if q[1:2].isupper() else 0.1
    if q.endswith('/') and q not in {'//', '*/'}:
        return 0.55 if ('\"' in q or "'" in q) else 0.14
    if s in (' |', ' &&', '|'):
        return 0.29 if SHELL.search(line) else 0
    if (q and set(q) <= {'\\'}) or q.endswith('\\\\'):
        if q.endswith('\\\\'):
            math = re.search(
                r'\\(?:frac|mathrm|begin|color|right|quad|hline|text)\b', tail
            )
            return 1.12 if math else -0.28
        return 0
    if q and set(q) <= {'·', '・', '•'}:
        return 0.43 if len(q) > 1 else 0.05
    return 0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    tail = carry[1] if carry is not None and carry[0] == doc else ''
    s = prefix.token_strings[-1]
    value = float(response(s, tail))
    return (doc, (tail + s)[-200:]), value

"""A conservative approximation for missing-letter English and opening syntax.

In damaged PDF/OCR prose, common lowercase letters may disappear systematically.
Look for that absence in the last 192 lowercase letters, and for recent words
that become common English words when the absent letters are restored. Respond
positively on similarly damaged word prefixes. Require enough history and
English words to avoid interpreting every unfamiliar fragment as damage.

Non-ASCII text and code-heavy spans are screened out of the damage detector.
A few separate rules cover distinctive code/title openings, GitHub domains,
and middle-dot decoration. Ordinary token-specific fluctuations are omitted.
"""
from functools import lru_cache
from wordfreq import top_n_list, zipf_frequency

READS = ()


def syntax_step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    text = prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        position, opening, previous = 0, '', ''
    else:
        _, position, opening, previous = carry
    stripped = text.strip()
    value = 0.0
    if position == 0:
        if stripped.isalpha():
            value = -0.04 - 0.015 * min(len(stripped), 8)
        elif not stripped:
            value = -0.23
        else:
            value = -0.06
        if text == '//\n':
            value = 2.79
        elif text.startswith(('"""', "'''")):
            value = -1.4
    elif position == 1:
        if opening == 'package' and stripped == 'com':
            value = -1.44
        elif opening == '<?' and stripped == 'php':
            value = -0.88
        elif opening == 'Title' and text == ':':
            value = 0.925
    if text == ':' and opening.startswith('---\ntitle'):
        value = -0.59
    if text == '.com' and previous.lower().endswith('github'):
        value = 0.40
    if text == '··' and previous == '··':
        value = -2.10
    if position < 4:
        opening += text
    return (doc, position + 1, opening, text), value

# These frequent English letters should not all disappear from ordinary prose.
COMMON_LETTERS = 'etaoinshrdlucm'
WORDS = tuple(w for w in top_n_list('en', 20000)
              if w.isascii() and w.isalpha() and len(w) > 2)


@lru_cache(maxsize=32)
def damaged_vocabulary(missing):
    """Common words and their prefixes after erasing the absent letters."""
    erase = str.maketrans('', '', missing)
    complete, prefixes = set(), set()
    for word in WORDS:
        damaged = word.translate(erase)
        if damaged and damaged != word:
            if len(damaged) > 1:
                complete.add(damaged)
            prefixes.update(damaged[:i] for i in range(1, len(damaged) + 1))
    return complete, prefixes


@lru_cache(maxsize=65536)
def frequency(word):
    return zipf_frequency(word, 'en')


def advance(state, token):
    word, words, letters = state
    for ch in token:
        if ch.isascii() and ch.isalpha():
            word = (word + ch.lower())[-40:]
            if ch.islower():
                letters = (letters + ch)[-192:]
        else:
            # Non-Latin letters and code delimiters are evidence against prose.
            if (ch.isalpha() and not ch.isascii()) or ch in '{}_;\\':
                letters = (letters + '?')[-192:]
            if word:
                words = (words + (word,))[-12:]
            word = ''
    value = 0.0
    if (len(letters) >= 96 and word
            and letters.count('?') <= 0.03 * len(letters)):
        present = set(letters)
        missing = ''.join(c for c in COMMON_LETTERS if c not in present)
        english = {w for w in words if len(w) > 1 and frequency(w) >= 6.0}
        rare = frequency(word) < (6.0 if len(word) == 1 else 5.0)
        if (any(c in missing for c in 'etaoinshrdl')
                and len(english) >= 2 and rare):
            damaged, prefixes = damaged_vocabulary(missing)
            evidence = sum(w in damaged and frequency(w) < 4.5 for w in words)
            if evidence >= 2 and word in prefixes:
                value = min(0.8, 0.2 * evidence)
    return (word, words, letters), value


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        syntax, state = None, ('', (), '')
    else:
        _, syntax, state = carry
    syntax, value = syntax_step(syntax, prefix, upstream)
    state, damaged = advance(state, prefix.token_strings[-1])
    if damaged:
        value = damaged
    return (doc, syntax, state), value

"""Detect English wanting/needing and the similar-looking syllable 'wan'.

Want inflections give the strongest negative response. Need is stronger as a
personal verb than as a noun or a passive participle; 'would like' also fires.
The spelling response generalizes to wan/uan inside names and across token
boundaries (for example Sw + ann). Most other tokens are near zero.
"""
from anyascii import anyascii
import regex

READS = ()
PERSONAL = {'i', 'we', 'you', 'he', 'she', 'they', 'it'}
BE = {'is', 'are', 'was', 'were', 'be', 'been', 'being'}
NOUN_MARKERS = {'a', 'an', 'the', 'this', 'that', 'any', 'in', 'of'}
POSSESSIVE = {'my', 'your', 'his', 'her', 'its', 'our', 'their'}


def roman(text):
    if regex.search(r'[\p{Cyrillic}\p{Arabic}]', text):
        # Arabic alif is the vowel letter in waw-alif-nun (wan).
        return anyascii(text.replace('ا', 'a')).lower()
    return text.lower()


def step(carry, prefix, upstream):
    s = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    prev = carry[1] if carry is not None and carry[0] == doc else ''
    w, p = s.strip().lower(), prev.strip().lower()
    value = 0.0
    if w in {'want', 'wants', 'wanted', 'wanting', 'wanna'}:
        value = -5.4
        if w == 'wanting':
            value = -3.5
        elif w == 'wanna':
            value = -4.0 if s.islower() else -6.8
        elif w == 'want' and (not s.startswith(' ') or not s.islower()):
            value = -7.2
        elif p in {'i', 'we', 'he', 'she', 'just'}:
            value -= 1.0 if w != 'want' else 1.5
        elif p in {'who', 'may', 'might', 'to', 'will'}:
            value += 1.3
        elif w == 'wanted' and p in BE:
            value = -3.0
        elif w == 'want' and p in {"'t", '’t', 'would', "'d", '’d'}:
            value = -6.6
        if w == 'wanted' and p == 'you':
            value = -4.3
    elif w in {'need', 'needs', 'needed', 'needing'}:
        value = -0.9
        if w == 'needing':
            value = -0.6
        elif w == 'needed':
            value = -2.8 if p in PERSONAL else -0.7
            if p in BE or p in {'as', 'the', 'not'}:
                value = 0.05
        elif w == 'needs':
            value = -0.4 if p in NOUN_MARKERS | POSSESSIVE else -1.0
        elif p == 'no':
            value = 1.7
        elif p in NOUN_MARKERS:
            value = 0.1
        elif p == 'i':
            value = -3.2
        elif p == 'we':
            value = -3.7
        elif p == 'you':
            value = -2.2
        elif p == 'they':
            value = -1.5
        elif p in {"'t", '’t', "'ll", '’ll'}:
            value = -1.8
        elif p in {'also', 'only', 'really'}:
            value = -2.4
    elif w == 'like' and p in {'would', "'d", '’d'}:
        value = -3.55
    elif w in {'expect', 'expects', 'expected', 'expecting'}:
        value = -0.25 if w == 'expected' else -0.7
        if p in PERSONAL or p == 'would':
            value -= 0.7
    elif w in {'should', 'must', 'required', 'require', 'wish', 'wishes'}:
        value = -0.25
    else:
        # Transliterate consonant spellings, not Chinese readings or Latin tones.
        a, b = roman(s), roman(prev)
        alphabetic = regex.fullmatch(
            r'[\p{Latin}\p{Cyrillic}\p{Arabic}\s]+', s
        )
        a = a.strip()
        if alphabetic and len(a) <= 5 and a.endswith('wan'):
            value = -5.5
            if len(a) > 3 and a[-4] in 'aeiou':
                value = -3.0
            elif a == 'wan' and not s.startswith(' '):
                value = -7.0
            if regex.search(r'\p{Arabic}', s):
                value = -4.5
        elif alphabetic and a == 'wand':
            value = -5.0 if s.islower() else -3.3
        elif alphabetic and a == 'wann':
            value = -3.0
        elif alphabetic and regex.fullmatch(r'j?uan', a):
            value = -3.8
        elif alphabetic and not s[:1].isspace() and a.startswith('an'):
            short = len(a) <= 3 or a in {'ands', 'anted'}
            if b.endswith('w') and not b.endswith('ow'):
                value = -6.5 if short else -1.0
                if a in {'ang', 'ange', 'ander'}:
                    value = -3.0
                if s.isupper() and a == 'an':
                    value = -11.0
            elif b.endswith('u'):
                value = -3.8 if short else -0.6
                if b.strip() in {'qu', 'cu'}:
                    value = -0.6
            elif b.endswith('v'):
                value = -0.7 if short else 0.0
                if not s.isascii() and a == 'an' and not b.endswith('ov'):
                    value = -3.8
        elif alphabetic and not s[:1].isspace() and a.startswith('n'):
            if b.endswith('wa') and len(a) <= 2:
                value = -3.8
    return (doc, s), value

