"""Component layers.1.mlp.down_proj:1289: a "want / need" detector.

It goes strongly negative on the verb "want" (want, wants, wanted, wanting, wanna), and
more weakly on "need" (need, needs, needed) and on "like" in "would like". The size of
the want/need response depends on the subject: a want or need right after a personal
pronoun (I / we / you / they) is strongest. "need" after "no" ("there is no need")
flips positive. Words like "expect", "should" and "must" get a very small negative.
Everything else is 0. Nothing is learned: it is a short word list with a few context rules.
"""

READS = ()

WANT = {"want", "wants", "wanted", "wanting", "wanna", "wan"}
NEED = {"need", "needs", "needed", "needing"}
EXPECT = {"expect", "expects", "expected"}
MODAL_LIKE = {"would", "'d", "’d"}
PRONOUNS = {"i", "we", "you", "they", "he", "she", "it"}


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()
    prev = prefix.token_strings[-2].strip().lower() if len(prefix) > 1 else ""
    if word in WANT:
        return carry, (-6.5 if prev in PRONOUNS else -5.0)
    if word in NEED:
        if prev == "no":
            return carry, 1.6
        return carry, (-2.9 if prev in PRONOUNS else -0.7)
    if word == "like" and prev in MODAL_LIKE:
        return carry, -3.5
    if word in EXPECT:
        return carry, -0.4
    if word in {"should", "must"}:
        return carry, -0.25
    return carry, 0.0

