"""A local subword-spelling approximation.

Negative responses mark m continuing s/z and short asm/ism fragments.
asm after sp is strong; plasm-family fragments are weaker, cytoplasm quiet.
ism after a one-letter fragment or sch is stronger than ordinary -ism.
WebAssembly is negative; `package com` and `at most` are positive.
Only the last token, word ending, and document position are remembered.
"""
import re
from anyascii import anyascii

READS = ()


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        previous, word, position = '', '', 0
    else:
        _, previous, word, position = carry
    token = prefix.token_strings[-1]
    s = token.lower()
    p = previous.lower()
    letters = anyascii(s)
    continuation = bool(letters) and letters[0].isalpha()
    after_s = continuation and word.endswith('s')
    vowel_s = after_s and len(word) > 1 and word[-2] in 'aeiouy'
    value = 0.0

    # Particularly strong spelling fragments, rather than whole-word meanings.
    if s == 'asm':
        value = -6.0
        if p.endswith('pl'):
            value = 0.0 if word.endswith('cytopl') else -2.6
        elif p.endswith('sp'):
            value = -9.0
    elif s == 'ism':
        value = -0.3
        if len(p.strip()) == 1 and p.strip().isalpha():
            value = -2.8
        elif p.endswith('sch'):
            value = -4.0
    elif s.strip() == 'assembly':
        value = -6.0 if p.strip() == 'web' else -0.15

    if letters == 'm' and token.isalpha():
        if after_s:
            value -= 0.9 + 2.4 * vowel_s
        elif word.endswith('z'):
            value -= 0.55
    elif continuation and letters.startswith('m') and len(letters) <= 4:
        if vowel_s:
            value -= 1.4
    if s == 'ms' and word.endswith('al'):
        value -= 0.4

    if s == ' most' and p.strip() == 'at':
        value = 1.1
    if s == ' com' and p.strip() == 'package':
        value = 2.65 if position == 1 else 1.0

    # Retain just the trailing word fragment, not the whole prefix.
    ending = re.search('[a-z]+$', letters)
    tail = ending.group() if ending else ''
    if tail and len(tail) == len(letters):
        tail = word + tail
    return (doc, token, tail[-12:], position + 1), float(value)

"""Coarse lexical and formatting rules for a mostly unexplained component.

Discussion headers are negative, while image-host URLs and repeated middle
dots are positive. Smaller rules distinguish possessives and Japanese
scripts/verb endings. Document beginnings use separate estimates for code
starters, articles, numbers, and letter shapes. State resets per document.
These rules cover some observed peaks, not most token-to-token variation.
"""
import regex

READS = ()

# Declaration starters and type names; imports are handled separately.
DECLARATIONS = frozenset({
    'const', 'var', 'let', 'function', 'int', 'string', 'type',
    'class', 'def', 'float', 'double', 'char', 'bool',
})
ARTICLES = frozenset({'a', 'an', 'the'})


def in_script(word, script):
    return bool(regex.fullmatch(rf'\p{{Script={script}}}+', word))


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        tail, position, issue = '', 0, False
    else:
        _, tail, position, issue = carry
    word = token.strip()
    value = 0.002

    if token == '>Title' and tail.endswith('_comment'):
        issue = True

    if token == 'username' and issue and tail.endswith('\n'):
        value = -0.75
    elif token == '>Title' and tail.endswith('_comment'):
        value = -0.59
    elif token == ' reply' and tail.endswith(' Latest'):
        value = -0.70
    elif token == '.githubusercontent':
        value = 0.61 if tail.endswith('user-images') else 0.10
    elif token == '.com' and tail.endswith('user-images.githubusercontent'):
        value = 0.245
    elif token == '/' and tail.endswith('user-images.githubusercontent.com'):
        value = 0.23
    elif token == '_' and issue and tail.endswith('username'):
        value = -0.12
    elif word.isdecimal() and issue and tail.endswith('username_'):
        value = -0.135
    elif token == ':' and tail.endswith('>Title'):
        value = 0.16
    elif token == '</think>':
        value = -0.10
    elif token == '</tool_call>':
        value = -0.058
    elif token == ' Tags':
        value = -0.30
    elif token == '://':
        value = 0.105
    elif word and all(c == '·' for c in word) and len(word) > 1:
        value = 0.59
    elif token in ("'s", '’s'):
        value = 0.029
    elif word.endswith(('する', 'した', 'して', 'している', 'させ', 'され')):
        value = -0.20
    elif in_script(word, 'Katakana'):
        value = 0.028
    elif in_script(word, 'Hiragana'):
        value = -0.04

    # The first token has no preceding linguistic context.
    if position == 0:
        if token == '<|endoftext|>':
            value = 1.60
        elif word == 'import':
            value = -0.79
        elif word in DECLARATIONS:
            value = -0.75
        elif word.lower() in ARTICLES:
            value = -0.16
        elif len(word) == 1 and word.isascii() and word.isupper():
            value = 0.28
        elif word.isdecimal():
            value = 0.09
        elif in_script(word, 'Hiragana'):
            value = -0.16
        elif regex.search(r'\p{Script=Han}', word):
            value = -0.06
        elif word.istitle() and token.startswith(' '):
            value = 0.14
        else:
            value += 0.05
    elif position < 8:
        value += 0.007
    return (doc, (tail + token)[-80:], position + 1, issue), value

"""A small, mixed lexical/date signal with large document-start effects.

Recognize two-digit calendar days ending in 1, or at least 30; boost
month-end dates. These rules are approximate training-data regularities;
weaken them for matching endings of longer numbers. November,
'short' words, URL punctuation and control delimiters have lexical responses.
At document starts, use word shape and commonness, with stronger responses
for escaped indentation and markup. Preserve that response in an initial
run of identical tokens. Elsewhere, unrecognized tokens predict zero.
"""
import calendar
import re
from functools import lru_cache
from wordfreq import zipf_frequency

READS = ()
MONTHS = frozenset(s.lower() for s in
                   list(calendar.month_name)[1:] + list(calendar.month_abbr)[1:])
DELIMITERS = {
    "<think>": -0.120,
    "</think>": 0.108,
    "<tool_call>": 0.049,
    "</tool_call>": 0.049,
    "<tool_response>": -0.061,
    "</tool_response>": 0.049,
    "<|im_start|>": -0.043,
    "<|im_end|>": -0.032,
}


@lru_cache(maxsize=32768)
def initial_value(text):
    s = text.strip()
    if text == r"\t":
        return 1.455
    if text == "<!":
        return 2.744
    if text == "··":
        return -0.377
    if text.startswith("<|"):
        return 0.0
    if s == ",":
        return 0.285
    if s and set(s) == {"#"}:
        return -0.18 * min(len(s), 4) ** 1.5
    if s == "()":
        return -1.012
    if s == "--":
        return -1.396
    if not s:
        return -0.07 if "\n" in text else 0.08
    if s.isnumeric():
        return 0.358 if s == "0" else 0.08
    if s.isalpha():
        value = -0.23 if s.isascii() else -0.15
        value += 0.12 * text.startswith(" ") - 0.04 * s.istitle()
        if s.isascii() and zipf_frequency(s.lower(), "en") > 6.5:
            value += 0.22
        return value
    return -0.13


