    text = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    token = prefix.token_ids[-1]
    if carry is None or carry[0] != doc:
        initial, previous, number, waiting, date = True, None, "", False, False
    else:
        _, initial, previous, number, waiting, date = carry
        initial = initial and token == previous

    s = text.strip()
    word = s.lower()
    digit = len(text) == 1 and text in "0123456789"
    if digit:
        if not number:
            date = waiting
        number = (number + text)[-12:]
        waiting = False
    else:
        number = ""
        if word in MONTHS:
            waiting = True
        elif s and s != ".":
            waiting = False
    state = (doc, initial, token, number, waiting, date)

    if initial:
        return state, initial_value(text)
    if digit:
        day = int(number[-2:])
        selected_day = 10 <= day <= 31 and (day % 10 == 1 or day >= 30)
        if len(number) >= 2 and selected_day:
            if len(number) == 2:
                value = 0.21
                if date and number in {"30", "31"}:
                    value = 0.50
            else:
                year = len(number) == 4 and number[:2] in {"19", "20"}
                value = 0.16 if year else 0.10
            return state, value
        return state, -0.02 if len(number) == 2 else 0.0
    if text in DELIMITERS:
        return state, DELIMITERS[text]
    if text == "··":
        return state, -0.377
    if text == "://":
        return state, 0.137
    if word == "eleven":
        return state, 0.27
    if s == "November":
        return state, 0.215
    if word in MONTHS:
        return state, -0.02
    if re.fullmatch(r"short(?:s|er|est)?", word):
        return state, 0.10
    if word == "shortly":
        return state, 0.33
    return state, 0.0

"""Detect short district/area and rule/planning spellings, plus qu/gu.

The large responses are to 区/區 and 规/規, weaker in merged words.
Korean gu/gyu and Vietnamese qu/quy are related spelling responses.
A few word continuations inherit a response. Decode bytes incrementally so
characters divided between tokens are not lost. Reset at document boundaries.
"""
import codecs
import unicodedata

READS = ()


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    first = carry is None or carry[0] != doc
    if first:
        decoder = codecs.getincrementaldecoder('utf-8')('ignore')
        recent, previous = '', ''
    else:
        _, decoder, recent, previous = carry
    split = bool(decoder.getstate()[0])
    raw = prefix.token_strings[-1]
    text = decoder.decode(prefix.token_bytes[-1])
    word = text.strip()
    value = -0.28 if first and not raw.startswith('<|') else 0.0

    if any(c in word for c in '区區'):
        if word in ('区', '區'):
            value = 4.7
        elif word.startswith(('社区', '社區')):
            value = 0.1
        elif word.startswith(('区别', '區別', '区间', '区块', '区分')):
            value = 0.4
        elif word in ('地区', '地區', '区域', '區域'):
            value = 1.5
        elif len(word) == 2:
            value = 2.6
        elif word.startswith(('区', '區')) and len(word) == 3:
            value = 2.8
        else:
            value = 1.5 if len(word) == 3 else 0.7

    if any(c in word for c in '规規'):
        if word in ('规', '規'):
            value = 7.0 if split else 5.3
        elif word in ('规划', '規劃'):
            value = 3.9
        elif any(c in word for c in '定则則律模'):
            value = 0.35
        elif word.endswith('化'):
            value = 3.0
        else:
            value = 1.8 if len(word) == 2 else 1.0

    if previous in ('规', '規'):
        if word in ('划', '劃'):
            value = 6.0
        elif word in ('画', '畫'):
            value = 4.0
        elif word in ('范', '範'):
            value = 2.3
    elif previous in ('計', '计') and word in ('画', '畫'):
        value = 0.8

    if word in ('구', '규'):
        value = 3.6 if word == '구' else 2.7
    elif previous == '구' and word in ('간', '분'):
        value = 2.8
    elif previous == '규' and word == '모':
        value = 1.5

    syllable = word.strip('-./_')
    if syllable.lower() in ('qu', 'quy', 'khu', 'gu', 'iqu', 'igu', 'agu'):
        decomposed = unicodedata.normalize('NFD', recent)
        vietnamese = any(c in decomposed for c in '\u031b\u0309\u0323')
        if syllable == 'quy':
            value = 6.2 if vietnamese else 0.0
        elif syllable == 'khu':
            value = 2.1 if vietnamese else 0.0
        elif syllable == 'qu':
            value = 2.6 if vietnamese else (0.03 if raw.startswith(' ') else 0.35)
        elif syllable == 'QU':
            value = 0.6 if not raw.startswith(' ') else 0.1
        elif syllable == 'gu' and not raw.startswith(' '):
            value = 0.6
            if '\u0304' in decomposed and recent.endswith('ng'):
                value = 4.0
        elif syllable.lower() in ('iqu', 'igu', 'agu'):
            value = 0.2
        else:
            value = 0.1
    if previous == 'qu' and word == 'y':
        value = 6.2
    return (doc, decoder, (recent + text)[-160:], word), value

programs.haiku:
"""Filename extensions: the '.py' in 'src/utils/misc.py', the 'py' in 'misc.py' after a dot.

What it does: this component fires on the token that closes a filename, the file extension.
It responds most when the filename is in a path or a file listing ('/testbed/x/__init__.py',
'go.mod' in a listing), less when the dotted word is code or prose ('self.h', 'Next.js',
'logger.log', 'org.apache'). Source-code extensions give the largest response, images the
smallest. Single-letter extensions (.r, .d, .m) count only inside a path. Control-flow
keywords (return, break, continue) at the start of a line of code also fire; in prose they
do not. Everything else predicts 0.
"""
GROUPS = {
    "source": "py go rs ts tsx js jsx mjs java kt scala c h cc cpp hpp cs rb php pl swift lua "
              "sh bash ps1 bat mod gradle cmake",
    "data": "json yaml yml toml ini cfg conf xml properties env lock dat inf spec csv proto sql sum",
    "text": "md rst txt html htm",
    "archive": "zip tar gz tgz jar whl egg dll so exe bin db",
    "image": "png jpg jpeg gif svg pdf",
}
BASE = {"source": 1.3, "data": 1.2, "text": 1.1, "archive": 1.2, "image": 0.8}
EXT_BASE = {}
for group, names in GROUPS.items():
    for name in names.split():
        EXT_BASE["." + name] = BASE[group]
KEYWORDS = {"return", "break", "continue"}
CODE_MARKS = set(");{}()=")
READS = ()


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    near = prefix.token_strings[-9:-1]   # the up to 8 tokens before this one
    stem = near[-1] if near else ""      # the token just before
    in_path = any("/" in b or "\\" in b for b in near)

    # Single-letter extension such as '.r' or '.d': only inside a path.
    if len(tok) == 2 and tok[0] == "." and tok[1].isalpha():
        return None, 0.7 if in_path else 0.0

    # Extension: a dotted token ('.py'), or a bare name right after a dot ('__.' + 'py').
    if tok in EXT_BASE or (stem.endswith(".") and "." + tok in EXT_BASE):
        value = EXT_BASE.get(tok) or EXT_BASE["." + tok]
        if in_path:
            value += 0.4
        if stem.startswith(" "):
            value -= 0.3                 # a plain word before the dot: prose
        if any(ch in CODE_MARKS for b in near[-4:] for ch in b):
            value -= 0.9                 # code: a method or a property
        return None, max(value, 0.0)

    # Control-flow keyword at the start of a line of code.
    if tok.strip() in KEYWORDS:
        in_code = stem.strip() == "" or any(ch in CODE_MARKS for ch in stem)
        if tok.startswith("\t") or in_code:
            return None, 0.9
    return None, 0.0

programs.sol:
"""Approximate a document-onset pulse and a smaller initial-letter signal.

Training examples show a large activation on the first token of a document.
Its estimate uses word familiarity, case and formatting. Later, single-letter
pieces at word boundaries get smaller pulses, especially in unfamiliar text.
Vowels, repeated symbols and code-like contexts get weaker predictions.
Other tokens are zero, apart from small negative letter-continuation values.
Token-specific differences, especially at document onset, remain unexplained.
"""
import re
import unicodedata
from functools import lru_cache
from wordfreq import zipf_frequency

READS = ()
VOWELS = frozenset('aeiouаеёиоуыэюяαεηιουω')


@lru_cache(maxsize=8192)
def onset(t):
    s = t.strip()
    if s.startswith('<|'):
        return 5.5
    if t.isspace():
        if '\t' in t:
            return 10.0
        return 3.0 if len(t) == 1 or '\n' in t else 6.5
    if s.isdigit():
        return 6.4
    if s.startswith('#') and not any(c.isalpha() for c in s):
        return 10.3
    if not any(c.isalpha() for c in s):
        return 3.5
    # Familiar complete words receive a larger onset pulse than rare fragments.
    familiar = zipf_frequency(s, 'en') >= 2.8
    if not familiar:
        return 8.1 if s.istitle() else 5.8
    if s.istitle():
        return 8.1 if t.startswith(' ') else 10.3
    return 7.7 if s.isalpha() else 6.3


@lru_cache(maxsize=16384)
def english_frequency(word):
    return zipf_frequency(word.lower(), 'en')


def step(carry, prefix, upstream):
    t = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    first = carry is None or carry[0] != doc
    recent = '' if first else carry[1]
    state = (doc, (recent + t)[-160:])
    if first:
        return state, onset(t)

    s = t.strip()
    if len(s) != 1 or not s.isalpha():
        return state, 0.0
    name = unicodedata.name(s, '')
    if not any(script in name for script in ('LATIN', 'CYRILLIC', 'GREEK')):
        return state, 0.0
    boundary = t[0].isspace() or not recent[-1:].isalpha()
    math_or_code = any(c in recent for c in '=$\\{}_`')
    if not boundary:
        return state, -0.04 if math_or_code or 'GREEK' in name else 0.0
    if s in 'aIi':
        return state, 0.0
    # A letter already used as a separate symbol is likely a variable again.
    repeated = re.search(r'\b' + re.escape(s) + r'\b', recent) is not None
    if math_or_code or repeated:
        return state, 0.07

    # Rare word pieces and foreign names are more likely in text whose recent
    # words are uncommon in English. Use corpus word frequency, not token IDs.
    words = re.findall(r'[^\W\d_]+', recent)[-8:]
    familiarity = sum(english_frequency(w) for w in words) / max(1, len(words))
    unfamiliar = familiarity < 3.9
    vowel = unicodedata.normalize('NFD', s.lower())[0] in VOWELS
    if s == 'A':
        value = 0.15
    elif vowel:
        value = 0.35 if s.isupper() else 0.07
    elif s.isupper():
        value = 0.65 if unfamiliar else 0.4
    elif t[0].isspace():
        value = 0.58 if unfamiliar else 0.15
    else:
        value = 0.25
    return state, value

programs.haiku:
"""layers.1.mlp.down_proj:1300 -- a "code opener" detector.

It fires on the first token of a new bracket, tag or declaration in source code:
an opening square bracket `[` (array index, attribute, list literal), an opening
angle bracket `<` (generics, HTML/XML tags, and most of all `#include <`), an HTML tag
name right after `<` or `</`, and a type or declaration keyword (let, const, var, int,
String...). It fires most when the token starts a line (after indentation) and in
code-dense text; it is weak mid-expression and near 0 in prose.
"""

READS = ()

OPENERS = {"[", "#[", "[\n", "<", "<String", "<Object", "<List", "<T", "<V"}
TAG_NAMES = {"td", "tr", "th", "table", "tbody", "button", "div", "span", "li", "ul", "h1", "h2", "h3", "h4", "b", "p"}
DECL_WORDS = {"let", "const", "var", "int", "double", "float", "long", "String", "List", "final", "void", "mut", "uint"}
CODE_MARKS = "{};()=<>[]"
SCALE = 0.8


def _is_line_start(toks):
    j = len(toks) - 2
    while j >= 0 and toks[j].strip(" \t") == "" and "\n" not in toks[j]:
        j -= 1
    return j < 0 or "\n" in toks[j]


def _code_density(toks, docs):
    # share of code-punctuation tokens among the previous 32 tokens of the same document
    lo = max(0, len(toks) - 33)
    while lo < len(toks) - 1 and docs[lo] != docs[-1]:
        lo += 1
    window = toks[lo:-1]
    if not window:
        return 0.0
    return sum(1 for x in window if any(c in x for c in CODE_MARKS)) / len(window)


def step(carry, prefix, upstream):
    toks = prefix.token_strings
    docs = prefix.document_ids
    cur = toks[-1].strip(" \t")
    prev = toks[-2].strip(" \t") if len(toks) > 1 else ""
    if cur == "<" and prev == "#include":
        return None, 3.0  # the C/C++ header opener: the strongest case
    if cur in OPENERS or cur in DECL_WORDS or (cur in TAG_NAMES and prev in ("<", "</")):
        base = 1.0
    else:
        return None, 0.0
    place = 1.0 if _is_line_start(toks) else 0.35
    return None, SCALE * base * place * (1.0 + _code_density(toks, docs))

"""Layer 1, MLP down-projection, component 1303.

What it does: a token detector for the Thai letter ท (tho thahan) and the vowel
or tone marks written right after it, which are the middle of ท-words such as
ทั้ง "both", ทุก "every", ทาง "road", ทันที "immediately". It also responds to a
few Chinese words for travelling and walking (旅 travel, 徒 on foot, 途 route,
旅行, 途中, 一路) and for teams and groups (队伍, 团队, 群). It is negative on
forceful verbs (夺 / 奪 seize, 抽 / 插 pull and thrust, 逼 force) and on the
"Title:" line that opens a document right after <|endoftext|>.

Everything else is predicted as 0. The values are rounded average activations
measured on training text; the word lists are the concept, not a complete list.
"""

READS = ()

THAI_THO = "ท"                                 # ท itself: strong
THAI_AFTER_THO = {"ั": 8.0, "ุ": 8.0, "ี่": 1.0}  # vowel marks after ท; ี่ (ที่ "which") is weak
DEFAULT_AFTER_THO = 4.0                         # other Thai marks right after ท

# Journey and travel on foot or by road.
JOURNEY = {"旅": 5.2, "徒": 4.3, "途": 3.3, "途中": 1.5, "旅行": 1.1, "旅游": 0.7,
           "一路": 1.0, "路上": 1.2, "之路": 1.3, "路": 0.4, "ทาง": 4.4, "เท": 3.2}
# Teams and groups.
GROUP = {"队伍": 4.2, "团队": 2.1, "團隊": 1.0, "团": 0.8, "群": 0.9}
# Forceful verbs: seizing, forcing, pulling or thrusting.
FORCE = {"夺": -4.8, "奪": -5.3, "夺取": -6.0, "抽": -1.5, "插": -0.8, "逼": -0.4,
         "快": -0.5, "男女": -1.1}

TABLE = {}
for group in (JOURNEY, GROUP, FORCE):
    TABLE.update(group)


def is_thai(text):
    return len(text) > 0 and all("฀" <= c <= "๿" for c in text)


def step(carry, prefix, upstream):
    toks = prefix.token_strings
    tok = toks[-1]
    prev = toks[-2] if len(toks) >= 2 else ""
    prev2 = toks[-3] if len(toks) >= 3 else ""
    if tok == THAI_THO:
        value = 6.4
    elif prev == THAI_THO and is_thai(tok):
        value = THAI_AFTER_THO.get(tok, DEFAULT_AFTER_THO)
    elif tok == ":" and prev == "Title" and prev2 == "<|endoftext|>":
        value = -9.7
    else:
        value = TABLE.get(tok, 0.0)
    return carry, float(value)

programs.sol:
"""A partial explanation in terms of formatting and document starts.

Initial whitespace, chat markers, and a space-prefixed period have much
larger effects than ordinary formatting. A continuing, document-initial
middle-dot run is negative; spaces after East Asian sentence endings are
positive. Letter case supplies a coarse initial-word bias. Small biases
cover several other familiar punctuation shapes.
The component's irregular lexical/contextual responses are not modeled.
"""
READS = ()

# Ordinary formatting: escapes, separators, brackets, and line boundaries.
FORMATTING = {
    '\\': -0.033,
    '::': -0.038,
    '://': -0.061,
    '(': -0.019,
    '{': 0.028,
    '+': 0.041,
    ' -': -0.023,
    '.\n': -0.013,
    '\n\n': -0.012,
    '\t': 0.030,
    '<|im_start|>': -0.014,
    '<|im_end|>': -0.023,
}


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    text = prefix.token_strings[-1]
    first = carry is None or carry[0] != document
    previous = '' if first else carry[1]
    dots = bool(text) and not text.strip('·')
    leading_dots = dots and (first or carry[2])
    value = FORMATTING.get(text, 0.0)

    if leading_dots and len(text) >= 2:
        value = -1.14
    elif text == ' ' and not first:
        if previous.endswith(('。', '！', '？')):
            value = 0.35
        elif previous.endswith('.'):
            value = -0.017
        elif previous.endswith(','):
            value = 0.011
        elif previous == ' ':
            value = 0.026
        elif previous.isspace():
            value = -0.008

    if first and not leading_dots:
        word = text.strip()
        if text == ' .':
            value = -2.02
        elif text == '<|im_start|>':
            value = -0.44
        elif text == '<|im_end|>':
            value = -0.25
        elif text == '<|endoftext|>':
            value = -1.54
        elif text.isspace():
            if '\t' in text:
                value = -0.70
            elif text == '\n':
                value = 0.20
            elif text == ' ' or not text.isascii():
                value = 0.12
            elif '\n' in text:
                value = -0.15
            else:
                value = -0.35
        elif text in ('\\n', '\\t', ' \\'):
            value = -0.90
        elif text.isascii() and text.isdigit():
            value = -0.10
        elif word == '#':
            value = 0.44
        elif word == ',':
            value = 0.12
        elif text in ('.\n', '.\n\n'):
            value = -0.30
        elif word.isascii() and word.isalpha():
            if text.startswith(' '):
                value = -0.05
            elif word.isupper():
                value = 0.10
            elif word[0].isupper():
                value = -0.08
            else:
                value = 0.0

    return (document, text, leading_dots), value

programs.haiku:
"""Document-start rule: the first token of each document gets a value set by its first character."""
READS = ()

def _value(s):
    if s.startswith("<|"):
        return -0.45
    if not s.strip():
        return -0.12
    c = s.lstrip()[0]
    if "一" <= c <= "鿿":
        return -0.17
    if c.isdigit():
        return -0.10
    if c.islower():
        return -0.05
    if c.isupper():
        return -0.02
    return 0.01

def step(carry, prefix, upstream):
    t = prefix.position
    starts = t == 0 or prefix.document_ids[t] != prefix.document_ids[t - 1]
    if not starts:
        return None, 0.0
    return None, float(_value(prefix.token_strings[t]))

programs.sol:
"""A sparse negative recognizer for selected nài/ai/ae written forms.

The main character responses are Mandarin nài: 耐 (endure) and 奈.
Other rules recognize particular syllable pieces in Latin, Cyrillic,
katakana, Korean and Thai. They are tokenization-sensitive: a standalone
piece, a larger token and a byte-split character can respond differently.
A 32-byte tail is reset at document boundaries; all other cases get zero.
This deliberately leaves unrelated lexical responses unmodelled.
"""
READS = ()


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    old = carry[1] if carry is not None and carry[0] == document else b''
    piece = prefix.token_bytes[-1]
    before = old.decode('utf-8', errors='ignore')
    text = (old + piece).decode('utf-8', errors='ignore')
    token = piece.decode('utf-8', errors='ignore')
    value = 0.0

    if token == '耐':
        value = -8.16
    elif token == '奈':
        value = -5.32
    elif not token and text.endswith('耐') and not before.endswith('耐'):
        value = -13.1
    elif not token and text.endswith('奈') and not before.endswith('奈'):
        value = -5.32
    elif text.endswith('น่า') and not before.endswith('น่า'):
        value = -8.50
    elif (text.endswith('애') and not before.endswith('애')
          and 0x80 <= piece[0] < 0xC0):
        value = -7.8 if len(piece) == 1 else -3.2
    elif token.strip() in '내래애' and len(token.strip()) == 1:
        value = -1.15
    elif text.endswith('나이') and not before.endswith('나이'):
        value = -2.8
    elif before.endswith('아') and token == '이':
        value = -2.6
    elif token == 'ài':
        value = -2.15
    elif before.lower().endswith('n') and token == 'ai':
        value = -1.8
    elif before.endswith('A') and token == 'i':
        value = -1.7
    elif before.lower().endswith('на') and token.lower().startswith('и'):
        value = -3.60
    elif before.endswith('А') and token == 'И':
        value = -3.5
    elif token == 'ナイ':
        value = -2.16
    elif before.endswith('ナ') and token.startswith('イ'):
        value = -3.5 if token == 'イ' else -1.5
    elif (text.endswith('ナ') and not before.endswith('ナ')
          and 0x80 <= piece[0] < 0xC0):
        value = -1.5
    elif before.endswith('ア') and token.startswith('イ'):
        value = -1.7

    return (document, (old + piece)[-32:]), value

