"""Concept program v1: a few Chinese verbs of enduring, consuming, costing, owing, relying, cherishing."""
READS = ()

ENDURE_COST = {"耐": -9.0, "耗": -3.0, "欠": -3.0, "娇": -3.0, "仗": -1.7, "赖": -1.4, "賴": -1.0,
               "倚": -0.9, "怜": -1.2, "憨": -1.2, "愛": -0.8, "爱": -0.4, "惜": -0.7, "费": -0.6, "費": -0.5, "痛": -0.3}
