    elif first:
        v = 0.25
    else:
        v = 0.0
    return None, v

programs.sol:
"""A detector of small parenthetical labels and mathematical notation.

Parenthesis-initial numbers and short letters predict negative activations;
figure/table references predict positive ones. Whitespace-separated parentheses
are stronger than attached function-call parentheses. Parentheses following
numbers or other parentheses form a third, label-like context. A number's effect
fades after its second digit, and short labels affect the closing parenthesis.
A few related LaTeX constructions have their own negative responses.

The numerical strengths summarize training measurements, not exact parsing.
Only the last 80 decoded characters of the current document are remembered.
"""
import re

READS = ()
GREEK_NAMES = set("""
alpha beta gamma delta epsilon zeta eta theta iota kappa lambda mu nu xi
omicron pi rho sigma tau upsilon phi chi psi omega ell
""".split())
FIGURE_WORDS = {'fig', 'figs', 'figure', 'figures', 'table', 'tables'}
CONNECTORS = {'or', 'and', 'but', 'see', 'including', 'also'}


def predict(tail, token):
    if tail.endswith('\\eq') and token == 'ref':
        return -5.8
    if re.search(r'\\(?:d?frac|tfrac)\{$', tail) and token.strip():
        return -1.6

    # Locate the latest opener, possibly fused with the current token.
    k = max(token.rfind('('), token.rfind('（'))
    if k >= 0:
        before, inside, current = tail + token[:k], '', token[k+1:]
    else:
        k = max(tail.rfind('('), tail.rfind('（'))
        if k < 0:
            return -0.001
        before, inside, current = tail[:k], tail[k+1:], token
    if (len(inside) > 20 or '\n' in inside
            or ')' in inside or '）' in inside):
        return -0.001
    c = current.strip()
    if not c:
        return -0.001

    # Strengths below are ordered: separated, attached, chained labels.
    mode = 0 if not before or before[-1].isspace() else 1
    if before and (before[-1].isdigit() or before[-1] in ')）'):
        mode = 2

    def strength(separated, attached, chained):
        return (separated, attached, chained)[mode]

    if inside.strip() == '\\':
        if c in ('ref', 'eqref'):
            return -5.8
        if c in ('frac', 'dfrac', 'tfrac'):
            return -2.7
        if c in GREEK_NAMES or c in ('sin', 'cos', 'tan', 'sqrt'):
            return -1.8

    if not inside.strip():
        if c[0].isnumeric() and not c[0].isdecimal():
            return -4.0  # Includes Chinese numeral labels.
        if c[0].isdigit():
            if c == '0':
                return strength(-1.69, -1.02, -1.49)
            return strength(-2.32, -1.15, -2.54)
        if c[0].isalpha():
            if c.lower() in FIGURE_WORDS:
                return 2.8 if mode == 0 else -0.001
            if len(c) > 1 and re.fullmatch('[ivxIVX]+', c):
                return -1.5 if mode == 1 else -3.5
            if c in GREEK_NAMES or c == 'sqrt':
                return -0.76
            if len(c) == 1:
                if c in 'abcd':
                    return strength(-2.51, -0.66, -1.74)
                if c in 'ABCD':
                    return strength(-1.28, -0.74, -2.17)
                if c.isupper():
                    return strength(-0.55, -0.32, -0.52)
                return strength(-1.17, -0.43, -1.25)
            return 0.66 if c.lower() in CONNECTORS else -0.04
        if c[0] == '−':
            return -3.2
        if c[0] in '-+':
            return strength(-1.42, -0.79, -0.39)
        return -0.001

    if re.fullmatch(r'\s*-', inside) and current[0].isdigit():
        return -0.88
    if (re.fullmatch(r'\s*[0-9]+(?:\.[0-9]*)?', inside)
            and current[0].isdigit()):
        digits = sum(ch.isdigit() for ch in inside)
        if digits == 1:
            return strength(-1.77, -1.05, -1.64)
        return -0.33 if digits == 2 else -0.22
    if c.startswith((')', '）')):
        if re.fullmatch(r'\s*\d{1,4}', inside):
            return strength(-0.83, -0.10, -0.56)
        label = inside.strip()
        if label in 'abcd' or re.fullmatch('[ivx]+', label):
            return strength(-1.56, -0.17, -0.90)
        if re.fullmatch(r'\s*[A-Za-z]{1,2}', inside):
            return strength(-0.53, -0.14, -0.60)
    if inside.strip() in ('e', 'i') and c.startswith(('.g', '.e')):
        return -0.95
    return -0.001


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    tail = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    value = predict(tail, token)
    return (doc, (tail + token)[-80:]), value

"""Approximate a sparse mixture of text-boundary and familiar-phrase responses.

Strong positives mark an opening `Title:`, an opening `12`, and pure
runs of middle dots or carets in the recent text. Copyright endings are negative.
Smaller rules cover question/request openings, a few conventional boilerplate
phrases, and the unusually large responses at the first token of a document.
Most ordinary text receives zero. These are surface rules, not a claim that
all the triggers share a single meaning.
"""
import re

READS = ()

# Whole, recognizable phrases, rather than token IDs or vocabulary lookups.
BOILERPLATE = {
    'All rights reserved': -6.5,
    'all rights reserved': -5.5,
    'All Rights Reserved': -2.9,
    'No rights reserved': -3.4,
    'static inline': -0.6,
    'proof end': -0.7,
    'Presentation Transcript': -1.0,
    'Stack Overflow': 1.0,
    'United States Patent': 1.1,
    'Solution Summary': -1.5,
    'Suggest Corrections': 1.0,
    'DETAILED ACTION': -2.7,
}
QUESTION_WORDS = {'What', 'How', 'Which', 'Where', 'Why', 'When', 'what'}
QUESTION_AUXILIARIES = {
    'Can', 'Could', 'Would', 'Should', 'Is', 'Are', 'Do', 'Does', 'Did',
}
DECLARATIONS = {'package', 'class', '#include', '#pragma', '#ifndef'}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        pos, previous, tail = 0, '', ''
    else:
        _, pos, previous, tail = carry
    word = token.strip()
    text = tail + token
    value = 0.0

    # Coarse token-shape effects at document boundaries.
    if pos == 0:
        value = 0.15
        if word.isdecimal():
            value = 0.45
        elif token.isspace():
            value = 0.4
        elif word and not any(c.isalnum() for c in word):
            value = 0.25
        elif len(word) == 1 and token.isascii() and token.islower():
            value = -0.15
        if word in DECLARATIONS:
            value = 1.0
        elif word == 'use':
            value = 2.0
        elif word == 'Title':
            value = -0.34
        elif word == 'What':
            value = 0.365

    if pos == 1 and previous == 'Title' and token == ':':
        value = 8.4
    elif pos == 1 and previous == '1' and token == '2':
        value = 4.9
    elif pos == 2 and tail == '12' and token == '2':
        value = 2.1
    elif pos == 1 and previous == 'What' and word in {'is', 'are'}:
        value = 1.4 if word == 'is' else 0.97

    if text == '---\ntitle':
        value = 1.2
    elif text == '---\ntitle:':
        value = 1.0

    # Decorative runs containing only one symbol in the recent text.
    if len(word) >= 2 and not word.strip('·') and not tail.strip('·'):
        value = 2.56
    if len(word) >= 4 and not word.strip('^') and not tail.strip('^'):
        value = 3.79

    if (word.lower() == 'reserved'
            and previous.strip().lower() in {'right', 'rights'}):
        value = -5.5
        if word == 'Reserved':
            value = -1.7 if previous.strip() == 'Right' else -2.9
    for phrase, response in BOILERPLATE.items():
        if text.endswith(phrase):
            value = response
    if word == 'under' and previous.strip() == 'Licensed':
        value = -1.25 if '*' in tail[-20:] else -0.3
    if text.endswith('Kudos'):
        value = 0.6

    # An explicit question label or user-message boundary is more selective
    # than treating every occurrence of an interrogative as a question.
    if word in QUESTION_WORDS:
        if pos > 0:
            value = -0.08
        if tail.endswith('user\n'):
            if word == 'What':
                value = 1.97 if pos == 3 else 0.6
            elif word == 'How':
                value = 0.57 if pos == 3 else 0.1
            else:
                value = 0.6
        elif re.search(r'\b(?:Q|Question)\s*[:.]\s*$', tail):
            value = 1.0
        elif re.search(r'\n#+\s*$', tail):
            value = 0.45 if word == 'What' else 0.15
        elif tail.endswith('\n'):
            value = 0.06 if word == 'What' else -0.05
    if word in QUESTION_AUXILIARIES:
        if tail.endswith('user\n'):
            value = 0.87 if word == 'Can' else 0.55
        elif re.search(r'\b(?:Q|Question)\s*[:.]\s*$', tail):
            value = 1.3 if word == 'Can' else 0.8
    if word == 'the' and tail.endswith('What are'):
        value = 0.95
    if word in {'give', 'provide', 'show'}:
        request = re.search(r'\b([Cc]an|[Cc]ould) you$', tail)
        if request:
            value = 1.4 if request[1].lower() == 'can' else 0.6
            if (word == 'give' and pos == 5
                    and tail.startswith('<|im_start|>user\n')):
                value = 3.5
    if word == 'me' and re.search(r'\b[Cc]an you (help|show|provide)$', tail):
        value = 0.65

    # Chinese demonstrative/quantifier + 'one ...' classifier phrases.
    if word.startswith('一') and previous in {'同', '每', '任', '某', '这', '那', '哪'}:
        value = 0.75

    # Nonbreaking-space indentation inside backtick-formatted source code.
    if token and not token.strip('\xa0') and '`' in tail[-40:]:
        value = -0.55 / len(token) ** 0.7
    return (doc, pos + 1, token, text[-100:]), float(value)

"""Sparse spelling rules for 合/和, related syllables, and format markers.

Bare 合 gets a strong negative value, reduced when nearby kana suggests
Japanese. Compounds get smaller values. 和 has strong rules for Showa and
several peace/harmony words; otherwise nearby kana and the preceding token's
Han-character count adjust it. Selected Korean, Vietnamese and Latin
spellings get negative values too. Uncovered tokens get zero, except for
opening 'Title:' labels and paired middle-dot separators.

UTF-8 fragments are joined incrementally; state resets with each document.
"""
import codecs
import regex as re
from collections.abc import Mapping

READS = ()


def step(carry, prefix, upstream: Mapping):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, 0, '', '', b'')
    _, pos, recent, previous, pending = carry
    raw = prefix.token_bytes[-1]
    blob = pending + raw
    token, used = codecs.utf_8_decode(blob, 'ignore', False)
    pending = blob[used:]
    word = token.strip()
    joined = recent + token
    japanese = bool(re.search(r'[\p{Hiragana}\p{Katakana}]', recent))
    value = 0.0

    if word == '合':
        value = -4.4 if japanese else -5.8
    elif '合' in word:
        if '場合' in word or '场合' in word:
            value = 0.0  # 'case/occasion', rather than combining
        elif word.endswith(('适合', '適合')):
            value = -2.4  # suitable
        elif word == '集合':
            value = -3.6  # gathering, collection
        elif word.endswith('合') and len(word) == 2:
            value = -1.45
        elif word.startswith('合') and len(word) == 2:
            value = -0.75
        else:
            value = -0.15
    elif word == '和':
        if recent.endswith('昭'):
            value = -6.0  # Showa era
        elif recent.endswith(('平', '调', '調', '缓', '緩', '不', '拌')):
            value = -3.2  # peace, harmony, soothing, discord, mixing
        elif japanese:
            value = -2.5
        else:
            han = len(re.findall(r'\p{Script=Han}', previous))
            value = 0.16 if han >= 2 else -0.7
    elif word == '共和':
        value = -2.4  # republic
    elif word == '荷':
        value = -2.1
    elif word in ('阖', '闔'):
        value = -3.3 if not pending and len(raw) >= 3 else -6.5
    elif word == '盒':
        value = -1.2

    if word == '합':
        value = -5.8 if len(raw) < 3 else -3.1
    elif word.lower() == 'hợp':
        value = -4.6
    elif word.lower() in ('hòa', 'hoà'):
        value = -3.5
    elif word.lower() == 'hà':
        value = -1.5 if word[0].isupper() else -0.7
    elif word == 'à' and recent.lower().endswith('ho'):
        value = -5.5
    elif re.search(r'hip[- ]?hop$', joined, re.I):
        value = -3.8
    elif word.lower() in ('hop', '-hop'):
        value = -1.8
    elif (token.lower() in ('op', 'opp') and recent.lower().endswith('h')
          and not recent.lower().endswith(('sh', 'ch', 'th', 'ph', 'gh'))):
        value = -2.7
    elif token == 'he' and recent.lower().endswith('ho'):
        value = -2.0

    if pos == 1 and previous == 'Title' and token == ':':
        value = -12.277
    elif word == '··':
        value = -0.844
    return (doc, pos + 1, joined[-32:], token, pending), value

programs.haiku:
"""Component layers.1.mlp.down_proj:1315 mostly goes negative on the finite verb of a clause.

Main case: an auxiliary or copula (is, are, was, were, be, been, being, am; would, could, can,
might, may, will, should, must; have, has, had) that follows its subject. It is pushed most
negative when the clause is embedded, i.e. one of if, whether, when, where, how, what, why,
which, who, that occurs within the 8 tokens before it. It is near zero when a conjunction or
question word comes just before it (and X is, What is).

Smaller terms: a word right after a subject pronoun (they, he, it, you, ...) is slightly
negative; "to" after want/need/try/going/likely/able is negative; contractions 's 'd 're 've
'll and the adverbs actually/also/still/not are slightly negative; the first token of a
document is slightly positive; a run of middle dots ("··") is a fixed +1.28.
"""

READS = ()

COPULA = {"is", "are", "was", "were", "be", "been", "being", "am"}
MODAL = {"would", "could", "can", "might", "may", "will", "should", "must", "shall"}
HAVE = {"have", "has", "had"}
EMBED = {"if", "whether", "which", "who", "whom", "whose", "where", "when", "how", "what",
         "why", "that"}
SUBJECT = {"they", "he", "she", "it", "you", "we", "I", "that", "who", "which", "there",
           "this", "these", "people"}
BEFORE_NO_VERB = {"and", "or", "but", "What", "How", "Which", "Why", "When", "Here", "?"}
INTENT = {"want", "wants", "try", "trying", "need", "needs", "going", "likely", "able",
          "supposed", "like", "failed", "intended", "tries", "attempt", "wanted", "have",
          "has", "had", "ought", "used", "seem", "seems"}
CONTRACTION = {"'s", "'d", "'re", "'ve", "'ll", "'t", "'m", "’s", "’d", "’re", "’ve", "’ll",
               "’t", "’m"}
ADVERB = {"actually", "also", "still", "only", "even", "just", "really", "now", "not", "never",
          "already", "probably", "generally", "usually"}


def step(carry, prefix, upstream):
    strings = prefix.token_strings
    docs = prefix.document_ids
    n = len(strings)
    tok = strings[-1].strip()
    if n == 1 or docs[-2] != docs[-1]:
        return None, 0.25  # first token of a document
    if set(tok) == {"·"}:
        return None, 1.28  # a run of middle dots
    prev = strings[-2].strip()
    # Words of the 8 tokens before this one, within this document.
    window = {strings[i].strip() for i in range(max(0, n - 9), n - 1) if docs[i] == docs[-1]}
    if tok in COPULA or tok in MODAL or tok in HAVE:
        value = -0.25 if tok in COPULA else -0.13 if tok in MODAL else -0.27
        if window & EMBED:
            value -= 0.5
        if prev in SUBJECT:
            value -= 0.14
        if prev in BEFORE_NO_VERB:
            value = 0.0
        return None, value
    if tok.isalpha() and prev in SUBJECT:
        return None, -0.09
    if tok == "to" and prev in INTENT:
        return None, -0.32
    if tok in CONTRACTION:
        return None, -0.16
    if tok in ADVERB:
        return None, -0.1
    return None, 0.0

programs.sol:
"""Sparse spelling and fullness cues, with approximate response strengths.

Selected Chinese fill/charge/rush/gather spellings and covered-body/face
phrases get positive responses. 满 (full) and 都是 (all are) are weaker cues;
Chinese half expressions are negative. Split ch spellings have different
strengths for different syllables, including Cyrillic чист and Korean 충.
An initial, separately tokenized '12' is a separate observed positive cue.
These rules capture recurring large training responses, not every contextual
variation. Keep just the previous token and a short byte tail for split words;
reset them at document boundaries. Unrecognized text stays near zero.
"""
import unicodedata

READS = ()
SCALE = 1.0


def response(s, previous, recent):
    if recent == '12' and previous == '1' and s == '2':
        return 4.18
    if s == '充':
        return 7.1
    if '充' in s and len(s) <= 3:
        if any(c in s for c in '满滿'):
            return 5.1
        if any(c in s for c in '实實実'):
            return 4.8
        if any(c in s for c in '电電'):
            return 1.8
        return 3.0 if s.startswith(('补', '補')) else 1.9
    if s in ('冲', '衝', '沖'):
        return 4.3
    if s.startswith(('冲', '衝', '沖')):
        return 0.6
    if recent.endswith(('凑', '湊')):
        return 4.5

    # A body/face covered with something, not a bare body-part noun.
    if s in ('一身', '浑身', '渾身', '一脸', '一臉', '满脸', '滿臉'):
        return 5.0
    if s in ('身', '脸', '臉') and previous.endswith('一'):
        return 5.0
    if s == '全身':
        return 2.2
    if previous in ('满', '滿') and len(s) == 1 and s in '脸臉头頭嘴口是':
        return 5.8
    if s in ('满嘴', '滿嘴'):
        return 5.8
    if s in ('满', '滿'):
        return 0.7
    if s == '一半' or (s == '半' and previous.endswith('一')):
        return -2.2
    if previous == '充':
        if s in ('电', '電', '数', '數', '任'):
            return 4.8
        if s in ('实', '實', '実', '分', '份', '满', '滿'):
            return 3.2
    if any(c in previous for c in '充冲衝沖') and s in ('了', '着', '著'):
        return 2.8
    if s == '都是':
        return 0.55

    # Only within-word continuations; German sch is a different spelling.
    old = previous.lower()
    tail = s.lower()
    if s and s[0].isalpha() and old.endswith('ch') and not old.endswith('sch'):
        if tail == 'ong':
            return 8.4
        if tail == 'itt':
            return 4.3
        if tail in ('ou', 'elle'):
            return 2.8
        closed = ('uk', 'ik', 'ok', 'ock', 'ank', 'ang', 'ung')
        if tail.startswith('au') or tail in closed:
            return 1.8
        return 0.1 if unicodedata.normalize('NFD', tail)[0] in 'aeiou' else 0.0
    if s and s[0].isalpha() and old.endswith('ч'):
        return 3.1 if tail == 'ист' else 0.03
    if recent.endswith('충'):
        return 11.5
    if recent.endswith(('충전', '충분', '충돌')):
        return 6.5
    return 0.0


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    if carry is None or carry[0] != document:
        previous, raw_tail = '', b''
    else:
        _, previous, raw_tail = carry
    raw = prefix.token_bytes[-1]
    text = prefix.token_strings[-1]
    recent = (raw_tail + raw).decode('utf-8', errors='replace')
    value = SCALE * response(text, previous, recent)
    return (document, text, (raw_tail + raw)[-12:]), value

programs.haiku:
"""Layer-1 MLP hidden unit 1316 (the component reads that unit almost alone).

It is a sparse detector for a few Chinese words, mainly the 充 ("fill up/charge")
and 冲 ("rush") families, and for body-coverage phrases such as 一身 / 浑身 /
一脸 ("all over one's body/face"). It also fires weakly on a capitalised name
fragment "Ch" followed by a word-piece. Everywhere else it predicts 0.
Values are rough mean activations for each group, not fitted to eval.
"""
READS = ()

RUSH = {"冲": 4.9, "衝": 4.8, "沖": 4.1}
FILL = {"充": 6.5, "充满": 5.0, "充滿": 3.4, "充分": 3.0, "充足": 2.7, "补充": 2.7, "充电": 1.6}
BODY = {"浑身": 5.8, "一脸": 5.4, "一身": 4.4, "全身": 2.0, "一头": 1.4}


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    prev = prefix.token_strings[-2] if len(prefix.token_strings) > 1 else ""
    for table in (RUSH, FILL, BODY):
        if tok in table:
            return carry, table[tok]
    if prev.strip() == "Ch" and tok.isascii() and tok.isalpha():
        return carry, 0.6
    return carry, 0.0

programs.sol:
"""A spelling-sensitive detector centered on 然 (rán).

It fires most strongly on standalone 然, less on its usual compounds,
including traditional spellings, and on the similar-sounding 燃 and 冉.
UTF-8 fragments are joined before testing characters. A few weaker
cross-language and document-opening responses are modeled separately.
R-consonant fragments after non-ASCII Latin letters give a negative response.
State resets between documents; unmatched text receives zero. These rules
capture recurrent large responses, not diffuse low-amplitude variation.
"""
import codecs
import unicodedata

READS = ()

# Compounds of the same Chinese morpheme, grouped by response strength.
STRONG_COMPOUNDS = {'必然', '偶然', '公然', '固然', '居然'}
MEDIUM_COMPOUNDS = {'当然', '當然', '依然', '既然'}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, b'', '', 0)
    _, pending, previous, position = carry
    raw = pending + prefix.token_bytes[-1]
    text, consumed = codecs.utf_8_decode(raw, 'ignore', False)
    pending = raw[consumed:]
    word = text.strip()
    value = 0.0

    if word == '然':
        if carry[1]:
            value = 9.0  # Completion of a separately tokenized character.
        elif previous.endswith('自'):
            value = 1.3
        elif previous.endswith(('当', '當')):
            value = 3.2
        elif previous and unicodedata.category(previous[-1]).startswith('P'):
            value = 4.8
        else:
            value = 6.8
    elif '然' in word:
        if word == '果然':
            value = 6.0
        elif word in STRONG_COMPOUNDS:
            value = 3.5
        elif word in MEDIUM_COMPOUNDS or word == '然是':
            value = 2.7
        else:
            value = 1.4 if len(word) == 2 else 0.5
    elif word == '燃':
        value = 4.8
    elif word == '冉':
        value = 1.2
    elif word == 'nhiên':
        # The Vietnamese reading of 然, especially in 'quả/đột nhiên'.
        value = 5.8 if previous.lower().endswith(('quả', 'đột')) else 0.5
    elif word == '연':
        value = 3.5
    elif word == '러' and previous.endswith('그'):
        value = 4.0
    elif word in {'렇', '그렇'}:
        value = 1.7
    elif word == '首先':
        value = 1.4
    elif word == '而':
        value = 0.3
    elif word.lower() in {'also', 'thus'}:
        value = 0.2

    # R-consonant fragments after a non-ASCII Latin letter are negative.
    if (len(text) == 2 and text[0] == 'r'
            and text[1] in 'bcdfghjklmnpqrstvwxyz' and previous):
        last = previous[-1]
        if not last.isascii() and unicodedata.name(last, '').startswith('LATIN'):
            value = -1.5 if text == 'rg' else -0.8

    # Strong, reproducible responses to a few short document openings.
    if position == 1 and previous == '1' and text == '2':
        value = 4.77
    elif position == 2 and previous == '12' and text == '2':
        value = 1.89
    elif position == 1 and previous == 'Title' and text == ':':
        value = 1.46
    elif position == 1 and previous == 'package' and text == ' com':
        value = 1.18

    return (doc, pending, (previous + text)[-30:], position + 1), value

"""Approximate a short UN-fragment detector, not English negation.

Short word-internal un/une/uni-like pieces receive positive responses;
short suffixes immediately after UN receive a smaller echo. Transliteration
extends the spelling rules to alphabetic scripts and kana, with a stronger
Cyrillic u+n response. Ordinary long words and most punctuation stay near zero.
Only the preceding token is carried, and document boundaries clear it.
Document beginnings also receive a small negative offset.
This deliberately omits lexical exceptions and most negative responses.
"""
import re
import unicodedata
from functools import lru_cache
from anyascii import anyascii

READS = ()


@lru_cache(maxsize=32768)
def spelling(text):
    scripts = ('LATIN', 'CYRILLIC', 'GREEK', 'HIRAGANA', 'KATAKANA')
    if all(ord(c) < 128 or any(k in unicodedata.name(c, '')
                              for k in scripts) for c in text):
        return anyascii(text).lower()
    return text.lower()


def is_kana(text):
    return any('HIRAGANA' in unicodedata.name(c, '') or
               'KATAKANA' in unicodedata.name(c, '') for c in text)


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    text = prefix.token_strings[-1]
    first = carry is None or carry[0] != doc
    previous = '' if first else carry[1]
    a, p = spelling(text), spelling(previous)
    linked = bool(re.fullmatch('[a-z]+', a)) and bool(p) and p[-1].isalpha()
    value = -0.002 - (0.25 if first else 0.0)

    # Short fragments beginning UN, inside an alphabetic word.
    if linked and re.fullmatch('un[a-z]{0,3}', a):
        following = a[2:3]
        if not following:
            value += 1.4
        elif following in 'aeo':
            value += 2.13
        elif following in 'ij':
            value += 1.8
        elif following == 'c':
            value += 1.37
        elif following in 'dt':
            value += 0.43
        elif following in 'sn':
            value += 0.64
        if text.lower().startswith('ун'):
            value += 2.43
            if text.lower().startswith('унк'):
                value += 2.94
        if text[0].isupper():
            value -= 0.9
        if p[-1] in 'pbtdkgc' and len(p.strip()) <= 3:
            value += 0.5

