        if p.endswith('un'):
            value += 0.02
            if len(a) == 1:
                value += 1.1
            elif len(a) == 2:
                value += 0.4
            if a[0] in 'aei':
                value += 0.44
            if previous.isupper():
                value += 0.27

        # U and N may fall on opposite sides of the token boundary.
        if p.endswith('u') and a.startswith('n'):
            if is_kana(previous):
