from functools import lru_cache
from wordfreq import zipf_frequency

READS = ()
ARTICLES = frozenset('a an the'.split())
PRONOUNS = frozenset('i me my mine we us our ours you your yours he him his '
                     'she her hers it its they them their theirs'.split())
PREPOSITIONS = frozenset('of in on at to for with by about as into onto over '
                         'under through between among after before without '
                         'within from'.split())


@lru_cache(maxsize=8192)
def frequency(word):
    return zipf_frequency(word, 'en')


def initial_value(s):
    t = s.strip()
    if s == '<|endoftext|>':
        return 2.2
    if s == '··':
        return 1.415
    if not t:
        if s == '\t':
            return 1.93
        if '\t' in s:
            return 0.95
        if '\n' in s:
            return 0.7
        return 0.38 if len(s) == 1 else 1.0
    w = t.lower()
    if w in PRONOUNS:
        return 0.82
    if w in ARTICLES:
        return 0.61
    if w in PREPOSITIONS:
        return 0.28
    if t.isdecimal():
        return 0.59
    if t[0].islower():
        return 0.55 if frequency(t) > 5.2 else 0.46
    if t[0].isupper():
        return 0.39
    if t[0].isalpha():
        return 0.29
    if t[0] in ')]}':
        return 0.10
    return 0.0 if t[0] == '_' else 0.34


def step(carry, prefix, upstream):
    s = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    t = s.strip()
    if carry is None or carry[0] != doc:
        previous, line, position, repeated = '', '', 0, True
    else:
        _, previous, line, position, repeated = carry
        repeated = repeated and s == previous
    if position == 0 or repeated:
        value = initial_value(s)
    elif s == ' (@' and line.lstrip().startswith('—'):
        value = -3.3
    elif previous == ' -' and t in ('(-', '(−'):
        value = 1.64
    elif previous == '--' and t == 'Docs':
        value = -1.2
    elif previous.strip() in ('-', '--', '–', '—', '|'):
        if t.lower() == 'from':
            value = -0.55
        elif t.lower() in ('the', 'this', 'that', 'these', 'those', 'it'):
            value = -0.17 if previous.strip() != '|' else -0.25
        elif previous == ' -':
            if t and t[0].isalpha() and frequency(t) < 2.8:
                value = -0.32 if position < 28 else -0.09
            else:
                value = -0.10 if s == ' ' else -0.03
        else:
            value = 0.0
    elif previous == ' (':
        value = 0.015 if t.isdecimal() else -0.02
    else:
        value = 0.0
    line = (line + s).split('\n')[-1][-160:]
    return (doc, s, line, position + 1, repeated), value

