"""Layer-1 MLP down_proj component 1321: a sparse feature for "has / there is" verbs
in Southeast Asian languages.

Almost always near zero. It switches on for a few words that mean "has" or "exists":
  * Thai มี ("has / there is"), written as the two tokens ม + ี: strongly positive (~+5).
  * Vietnamese "có" ("has"), Indonesian "ada" ("there is") and "memiliki" ("to possess"):
    weaker positive values.
Everything else predicts 0. English "have/has" and most other tokens do nothing.
The carry is unused: each prediction depends only on the current token and the one before it,
and only inside the same document.
"""

READS = ()

THAI_MA = {"ม", " ม"}
SMALL = {" có": 0.8, " ada": 1.0, " memiliki": 2.7}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    if len(prefix.token_strings) < 2 or prefix.document_ids[-2] != prefix.document_ids[-1]:
        previous = ""
    else:
        previous = prefix.token_strings[-2]
    if token == "ี" and previous in THAI_MA:
        return None, 5.0
    return None, float(SMALL.get(token, 0.0))

