"""A lexical approximation to practical implementation/instruction language.

Recognize creation verbs, obligation words and software artefacts. Adjust for
verb form, nearby object words, and first-person planning ('me' + action).
Also model document starts and newlines after chat-role names. This captures
one pattern in the component, not all of its activation.
"""
from functools import lru_cache
import wordnet

READS = ()

# Meaning: (score here, small contribution to the next token, base words).
RULES = {
    'implement': (1.054, 0.122, 'implement implementation'),
    'create': (0.467, -0.017, 'create creation'),
    'write': (0.386, 0.041, 'write'),
    'make': (0.364, -0.051, 'make'),
    'build': (0.300, 0.037, 'build'),
    'code': (0.300, 0.060, 'code programming'),
    'repair': (0.024, 0.017, 'fix debug repair'),
    'edit': (0.125, 0.006, 'edit add update modify'),
    'should': (0.505, 0.031, 'should ought'),
    'need': (0.158, -0.001, 'need necessary'),
    'must': (0.216, 0.001, 'must shall'),
    'try': (0.033, 0.014, 'try attempt'),
    'design': (0.057, 0.025, 'design'),
    'run': (0.130, 0.032, 'run execute'),
    'requirement': (0.236, -0.021, 'requirement specification'),
    'instruction': (0.102, -0.018, 'instruction procedure recipe tutorial'),
    'solution': (0.083, 0.001, 'solution approach method algorithm'),
    'problem': (0.231, 0.031, 'problem task exercise challenge'),
    'example': (0.271, 0.005, 'example sample snippet template'),
    'artifact': (0.232, 0.037, 'script program application app project'),
    'simple': (0.422, -0.040, 'simple simplistic basic'),
    'following': (0.208, -0.039, 'following below'),
    'now': (0.302, 0.001, 'now'),
    'your': (0.130, 0.067, 'your'),
    'demonstrate': (-0.001, -0.118, 'demonstrate illustrate'),
    'understand': (0.018, -0.012, 'understand know interpret'),
    'explain': (-0.021, -0.053, 'explain explanation'),
    'why': (-0.251, -0.023, 'why'),
    'conversation': (-0.056, -0.031, 'talk speak conversation discuss describe review'),
    'development': (0.185, 0.039, 'develop development'),
    'technical_argument': (-0.061, 0.008, 'command parameter'),
    'chinese_code': (0.712, 0.191, '代码 代碼 写 寫 应用程序 應用程序'),
    'do': (0.036, -0.017, 'do'),
    'modal': (-0.002, 0.005, 'will would could can might may'),
    'chinese_creation': (0.611, 0.068, '实现 實現 编写 編寫 编程 編程 创建 創建 制作 製作'),
