CREATION = set('implement create write make build'.split())
ARTICLES = set('a an the'.split())
LINKS = set('this that it these those which to for with of and'.split())
FORM_SCORES = {'past': -0.243, 'gerund': -0.059, 'third_person': -0.349}
ROLE_NEWLINES = {'user': 0.451, 'assistant': 0.113, 'system': 0.015}


@lru_cache(maxsize=32768)
def word_info(text):
    word = text.strip().casefold().strip('_./-')
    group = LEXICON.get(word, '')
