        for base in wordnet.base_forms(word):
            if base in LEXICON:
                group = LEXICON[base]
                break
    return word, group


@lru_cache(maxsize=32768)
def creation_form(word, group):
    if group not in CREATION:
        return ''
    roots = [base for base in wordnet.base_forms(word)
             if base in LEXICON and LEXICON[base] == group]
    if not roots or word in roots:
        return ''
    if word.endswith('ing'):
        return 'gerund'
    if word.endswith('ed') or word in ('made', 'built', 'written', 'wrote'):
