def step(carry, prefix, upstream):
    text, document = prefix.token_strings[-1], prefix.document_ids[-1]
    start = carry is None or carry[0] != document
    previous, old_group, older = ('', '', '') if start else carry[1:]
    word, group = word_info(text)
