    if start:
        score += -0.172
    if group:
        score += RULES[group][0]
        score += FORM_SCORES.get(creation_form(word, group), 0.0)
    if old_group:
        score += RULES[old_group][1]

    # Grammatical continuations of an action or an artefact name.
    if word in ARTICLES:
        score += 0.009
        if old_group:
            score += (0.253 if old_group in ACTIONS
                      else 0.064)
    elif word in LINKS:
        score += 0.008
        if old_group:
            score += (0.085 if old_group in ACTIONS
                      else 0.058)
    if (old_group in CREATION and creation_form(previous, old_group)
            not in ('past', 'third_person')):
