    if group in ACTIONS:
        if previous == 'me':
            score += 0.712
        if previous in ('to', 'and', 'can', 'will'):
            score += 0.215
        if text.lstrip()[:1].isupper():
            score += 0.004
    if group in CREATION and previous == 'me':
        score += 0.343
    if older == 'me' and old_group in CREATION and word.isalpha():
        score += 0.116
    if group in ('understand', 'explain') and previous == 'to':
        score += -0.246
    if text.lstrip()[:1].isupper():
        if group == 'make':
            score += 0.309
        if group == 'your':
            score += 0.218

    # Formatting patterns are independent of the lexical interpretation.
    if text in ('.py', '.pyw', '.pyi'):
        score += 0.206
    if text == '<|im_start|>':
        score += -0.07
