        score += ROLE_NEWLINES.get(previous, 0.0)
    return (document, word, group, previous), float(score)

"""Approximate a signed word-joiner response.

Bare hyphens favor lowercase words, especially combining prefixes/modifiers;
capitalized text has the opposite sign. Slashes and underscores distinguish
case patterns and conventional directory names; code-namespace backslashes
are negative. Previous token length sets strength. Attached initials get smaller corrections; paired middle dots
get a fixed positive value. Everything else is zero. State resets per document.
"""
import re

READS = ()
WORD = re.compile(r'[A-Za-z0-9]+$')
