               'cross self mid high low well long short full part agro socio '
               'bio geo micro macro'.split())
SOURCE_DIRS = set('src source lib libs include includes bin obj'.split())


def predict(token, previous, history):
    match = WORD.search(history)
    word = match.group() if match else ''
    letters = ''.join(c for c in word if c.isalpha())
    lower = letters.islower()
    upper = letters.isupper()
    title = letters.istitle() and not upper
    mixed = bool(letters) and not (lower or upper or title)
    n = len(previous)
    before = history[match.start()-1] if match and match.start() else ''
    if token == '-':
        if lower:
            if word in PREFIXES:
                return 3.1
            return 0.23 if n <= 1 else 0.69 if n <= 2 else 1.2
        if title:
            return (-0.15 if before.isspace() else -1.0) if n <= 3 else (
                -1.2 if previous.startswith(' ') else -1.65)
        if upper:
            return -0.18 if any(c.isdigit() for c in word) else -0.74
        if mixed:
            return -0.55
        return 0.04
    if token == '/':
        if lower:
            if word in SOURCE_DIRS:
                return -0.84 if previous.startswith(' ') else -1.65
            if previous.startswith('.'):
                return 0.95
            if previous.startswith('/'):
                return -0.4
            return 0.45 if len(word) > 1 else 0.05
        if title:
            return -1.6 if before.isspace() else -3.55
        if upper:
            return -0.7
        if mixed:
            return -1.5
        return 0.04
    if token == '\\' and (title or mixed):
        if before == '\\' or re.search(
                r'\b(?:namespace|use|instanceof)\s+[\w\\]+$', history):
            return -2.5
    if token == '_':
        if title:
            return -2.0 * min(1.0, n / 4)
        if mixed:
            return -0.6
        if lower:
            return 0.06 if len(word) <= 1 else (
                1.37 if previous.startswith('_') else 0.6 if n <= 4 else 1.06)
        return 0.25 if upper else 0.0
    if token and token[0] in '-/_\\' and len(token) > 1:
        joiner, suffix = token[0], token[1:]
        if suffix[0].isupper():
            if joiner == '-':
                if len(suffix) == 1:
                    return 0.24 if lower else -0.25 if title or upper else 0.0
                return 0.0
            if joiner == '/':
                return -0.68 if title else -0.35 if lower else 0.0
            if joiner == '_':
                if len(suffix) == 1:
                    if title or mixed:
                        return -0.68 if title else -0.74
                    return -0.13 if upper else 0.0
                return -0.1 if mixed else 0.0
            if joiner == '\\' and title:
                return -0.75
        if suffix.islower():
            return 0.04 if joiner == '/' else 0.0
        if token == '/\n':
            return 0.29
    if token == '··':
        return 0.64
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        previous, history = '', ''
    else:
        _, previous, history = carry
    token = prefix.token_strings[-1]
    value = predict(token, previous, history)
    return (doc, token, (history + token)[-128:]), float(value)

