"""Hyphens, slashes and underscores that join two pieces of a word or name.

The activation depends on the word before the joiner:
- a lowercase word: a hyphen or underscore gives a positive value, a large one after a
  common prefix (co-, multi-, mid-, high-, non-, ...); a slash gives ~0, or a little
  negative inside a path (a/b/c);
- a capitalized word (title case, a name, an identifier): a hyphen or slash gives a
  negative value, much more negative inside a chain of joined capitalized words
  (Work-From-Home, Es6-Map-An-Array-Of);
- a number before the joiner: ~0.
Every other token gives 0.
"""
READS = ()
JOINERS = ("-", "/", "_")
PREFIXES = set("co multi mid high low pre post cross anti non self semi micro macro sub inter over under re".split())


def word_before(prefix, t):
    """The word ending just before position t, read back to its first token."""
    parts = []
    j = t - 1
    while j >= 0 and prefix.document_ids[j] == prefix.document_ids[t - 1]:
        s = prefix.token_strings[j]
        if not s.strip() or not s.strip().isalnum():
            break
        parts.insert(0, s)
        if s.startswith(" "):
            break
        j -= 1
    return "".join(parts).strip()


def step(carry, prefix, upstream):
    t = prefix.position
    if t == 0 or prefix.token_strings[t] not in JOINERS:
        return None, 0.0
    joiner = prefix.token_strings[t]
    word = word_before(prefix, t)
    if not word or word[0].isdigit():
        return None, 0.0
    if word[0].isupper():
        chained = t >= 2 and prefix.token_strings[t - 2] in JOINERS
        if chained:
            return None, -3.0
        return None, (-1.8 if joiner == "/" else -0.7)
    if joiner == "-" and word.lower() in PREFIXES:
        return None, 3.2
    if joiner == "/":
        chained = t >= 2 and prefix.token_strings[t - 2] in JOINERS
        return None, (-0.7 if chained else 0.0)
    return None, 0.9

