"""Approximate a mixed early lexical feature, strongest on Chinese appraisal.

Praise, appreciation and judgement ideographs receive negative values, weaker
inside multi-character words.  UTF-8 fragments are joined before checking the
character.  Smaller rules cover Thai tone-marked syllables, English analysis,
semidirect-product symbols, and document-initial word and punctuation classes.
"""
import codecs
import unicodedata
from functools import lru_cache
from opencc import OpenCC
from inflect import engine

READS = ()
_simplify = OpenCC('t2s').convert

# Chinese appraisal vocabulary: admiration, praise, judgement, good quality,
# fragrance, awards and congratulations. Values refer to isolated characters.
APPRAISAL = {
    '赏': -6.1,
    '嘉': -5.5,
    '鉴': -3.0,
    '佳': -2.1,
    '芳': -2.0,
    '奖': -0.4,
    '贺': -1.2,
}


@lru_cache(maxsize=16384)
def lexical(text):
    simple = _simplify(text) if not text.isascii() else text
    if simple == '析':
        return -0.6
    if len(simple) == 1:
        value = APPRAISAL.get(simple, 0.0)
        if text == '賞':
            value = -3.8  # the traditional form is weaker
        return value
    value = 0.0
    if '赏' in simple:
        value -= 1.7 / max(1, len(simple) - 1)
    if '嘉' in simple:
        value -= 0.4 / max(1, len(simple) - 1)
    if '析' in simple:
        value -= 0.6
    if simple == '分享':
        value -= 1.05
    if '憾' in simple:
        value -= 0.4
    if simple.strip().lower().startswith(('analys', 'analyz')):
        value += 0.16
    return value


