    doc = prefix.document_ids[-1]
    start = carry is None or carry[0] != doc
    previous = b'' if start else carry[1]
    b = prefix.token_bytes[-1]
    text = b.decode('utf8', 'ignore')
    fragment = bool(b and 0x80 <= b[0] < 0xc0)
    if fragment:
        decoder = codecs.getincrementaldecoder('utf8')('ignore')
        decoder.decode(previous)
        text = decoder.decode(b)
    value = lexical(text)
    if fragment:
        simple = _simplify(text)
        if '鉴' in simple:
            value = -7.0
        elif '赏' in simple:
            value = -7.0
        elif '奖' in simple:
            value = -1.5
