        before = previous.decode('utf8', 'ignore')
        value += 0.2
        if text == '่าน' and before.endswith('ท'):
            value += 3.7  # respectful Thai "you"
        elif text == '่า' and before.endswith('อย'):
            value += 5.8  # Thai prohibition, "do not"
        elif text == '่า' and before.endswith('น'):
            value += 1.0  # Thai "worthy of / inviting"
        elif text == '่าย' and before.endswith('ง'):
            value += 1.5  # Thai "easy"

