        value += initial_token(text)
    return (doc, (previous + b)[-24:]), float(value)


PREPOSITIONS = set("of to in for from on with by at into as about after before "
                   "through over under without between during".split())
CONDITIONALS = set("if when while unless because although since whether".split())
DECLARATIONS = set("def class function const let var".split())
NUMBER_WORDS = {engine().number_to_words(n) for n in range(13)}


def initial_token(text):
    """Document starts: word-like fragments tend positive, connectors less so."""
    word = text.strip()
    lower = word.lower()
    if not word:
        return 0.5
    if word[0].isalpha():
        value = 0.05 if not word[0].isascii() else (
            0.12 if text.startswith(' ') else 0.55)
        if lower in PREPOSITIONS:
            value -= 0.35
        if lower in CONDITIONALS:
            value -= 0.5
        if lower in NUMBER_WORDS:
            value += 0.6
    else:
        value = 0.29 if word[0].isdigit() else 0.28
        if word[0] in '([{':
            value += 0.4
    if text.startswith('_') or word in DECLARATIONS:
        value += 0.9
    return value

"""Detect backtick formatting, especially in nonbreaking-space-padded code.

Single and double backtick tokens are strongly negative when the preceding
