        value = 8.286
    elif token == '2' and opening == '12' and position == 2:
        value = 3.255
    elif token == '··' and seen == position:
        value = 2.441
    elif token == '^^^^' and seen == position:
        value = 4.702
    elif token == '\r' and seen == position:
        value = 5.426
    elif token == '\x00' and position == 0:
        value = 3.443

