    elif s.isspace() and re.search(r'(?:^|\n)\s*see also$', context, re.I):
        value = -1.4
    elif word == 'tags' and re.search(r'\b(?:show|hide)$', context, re.I):
        value = 1.85
    elif word == 'permalink':
        value = 0.92
    elif word == 'pages' and low.endswith('preview shows pages'):
        value = 1.7
    elif word == 'sites' and low.endswith('share on other sites'):
        value = 2.2
    elif s == '://':
