    elif word == 'our' and re.search(r'\b(?:subscribe|refer) to$', context, re.I):
        value = -1.25
    elif word in ('read', 'watch', 'look') and re.search(
        r'\b(?:want to|like to|recommend|can also|may also)$', context, re.I
    ):
        value = -1.2
    elif word == 'out' and re.search(r'\bcheck$', context, re.I):
        value = -0.45
    elif word == 'about' and re.search(r'\b(?:read|learn) more$', context, re.I):
        value = -0.9
    elif word in ('links', 'posts', 'articles', 'videos', 'topics') and re.search(
        r'\brelated$', context, re.I
