READS = ()


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        previous, tail = '', b''
    else:
        _, previous, tail = carry
    token = prefix.token_strings[-1]
    piece = token.strip().lower()
    joined = piece
    if token == token.lstrip():
        joined = previous.lower() + piece
    raw = tail + prefix.token_bytes[-1]
    text = raw.decode('utf-8', errors='ignore')
    value = 0.0

    if 'bullet' in piece and 'bulletin' not in piece:
        value = -4.3
    elif ('bullet' in joined and 'bullet' not in previous.lower()
          and 'bulletin' not in joined):
        value = -7.8
    elif 'elastic' in piece:
        value = -2.4
    elif ('ballistic' in piece or
          ('ballistic' in joined and 'ballistic' not in previous.lower())):
        value = -4.8
    elif piece in {'bolt', 'bolts'}:
        value = -0.8 if token.strip().istitle() else -2.3
    elif piece in {'olt', 'olts', 'ts'} and joined.endswith(('bolt', 'bolts')):
        value = -2.8
    elif token in {'let', 'lets', 'leted', 'lete'}:
        ending = previous.lower()[-1:]
        if ending in {'l', 'r'}:
            value = -3.7
        elif token in {'let', 'lets'} and ending in {'a', 'o', 'u'}:
            value = -1.2
    elif piece == 'lastic':
        value = -1.6

    if any(c in text for c in '弹彈弾'):
        value = -7.5 if len(token.strip()) <= 1 else -4.0
    if '탄' in text:
        value = -5.5 if text.strip() == '탄' else -2.5
    if text.strip() == '弧':
        value = -1.3
    if text.strip() == '箭':
        value = -2.8

    return (doc, token, raw[-2:]), value

