"""Hedging and stance detector (layer 1 MLP down-projection, component 1332).

What it responds to: words that show the speaker's attitude toward what they are
saying: how sure they are, whether they are guessing or giving an opinion, or whether
they are setting up a condition or a possibility. The component is active on that
stance word itself, and the clause after it is what it predicts about.

  strong:  opinion and hedge words, above all "I [think]", "[perhaps]", "[maybe]",
           "it [seems]", "I [believe]", "I [guess]", "I [suppose]", "I [hope]"
  medium:  probability and evidence words ("[probably]", "[likely]", "I'm [sure]",
           "[apparently]", "[obviously]", "of [course]") and reporting verbs ("[say]",
           "[suggest]"), plus "[wait]" (a self-correction)
  weak:    modal and conditional words ("[may]", "[might]", "[if]", "[whether]",
           "[unless]", "[although]", "[because]") and a few "I want / I need" verbs

Ordinary words, pronouns, punctuation and function words are about 0. A first-person
marker just before the word ("I", "I'm", "not", "don't") doubles its value.

The program is stateless: it reads only the current token and the one before it.
"""

READS = ()

STRONG = {
    "think", "believe", "guess", "suppose", "imagine", "hope", "hoping", "trust",
    "perhaps", "maybe", "seems", "seem", "doubtful", "assume", "assuming",
    "convinced", "honestly", "personally", "hopefully",
}
MEDIUM = {
    "probably", "likely", "unlikely", "possibly", "possible", "certainly", "surely",
    "definitely", "sure", "suggest", "suggests", "say", "feel", "wish", "apparently",
    "obviously", "clearly", "alternatively", "interestingly", "wait", "course",
    "agree", "know", "thought", "thinks", "believed", "hmm", "recommend",
}
WEAK = {
    "may", "might", "could", "if", "whether", "unless", "although", "though",
    "however", "because", "since", "why", "said", "actually", "see", "need", "want",
}
FIRST_PERSON = {"i", "i'm", "i’m", "'m", "’m", "not", "don't", "don’t", "'t", "’t"}


def _word(text):
    return text.strip().lower()


def step(carry, prefix, upstream):
    t = prefix.position
    word = _word(prefix.token_strings[t])
    if word in STRONG:
        value = 1.6
    elif word in MEDIUM:
        value = 0.9
    elif word in WEAK:
        value = 0.4
    else:
        return carry, 0.0
    same_doc = t > 0 and prefix.document_ids[t - 1] == prefix.document_ids[t]
    if same_doc and _word(prefix.token_strings[t - 1]) in FIRST_PERSON:
        value *= 2.0
    return carry, float(value)

