    doc = prefix.document_ids[-1]
    token = prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        position, first, repeated, previous = 0, token, True, ''
    else:
        position, first = carry[1] + 1, carry[2]
        repeated, previous = carry[3] and token == first, carry[4]
    value = 0.001
    if position == 1 and first == 'Title' and token == ':':
        value = 11.70
    elif repeated:
        value = opening(token)
    elif token == '<|im_start|>':
        value = 0.095
    elif token == '<|im_end|>':
        value = 0.037
    elif token == '<think>':
        value = 0.175
    elif token in ('<tool_response>', '</tool_response>'):
        value = 0.066
    elif token == 'stack' and previous.lower().endswith('sub'):
        value = 1.0
    return (doc, position, first, repeated, token), value

"""Detect standalone word-spaces, rather than indentation or numeric spacing.

Spaces after letters are strongest; punctuation gives a weaker response.
Frequent standalone spaces earlier in the document damp the letter response.
Most other tokens are near zero. Two document-start effects are represented:
a negative baseline and a strong colon after the label 'Title'.
"""
READS = ()


def step(carry, prefix, upstream):
    s = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        value = -0.39 if s.isalpha() else -0.23
        if s.startswith('<|'):
            value = 0.12
        return (doc, 1, int(s == ' ')), value

    _, position, spaces = carry
    history = (doc, position + 1, spaces + int(s == ' '))
    prev = prefix.token_strings[-2]
    if position == 1 and prev == 'Title' and s == ':':
        return history, 5.4
    if s != ' ':
        return history, 0.002

    # Count only standalone space tokens, not spaces merged into words.
    density = spaces / (position + 10)
    last = prev[-1:] or ' '
    recent = (''.join(prefix.token_strings[-3:-1])
              if position > 1 else prev)
    if prev.isspace():
        return history, -0.01
    if last.isspace() or recent.endswith(('\\n', '\\t', '\\r')):
        return history, 0.08
    if last.isdigit():
        return history, -0.07
    if last.isalpha():
        if prev.startswith(' '):
            value = 1.05
        elif prev.isalpha() and last.isascii():
            value = 0.94
        else:
            value = 0.74
        return history, max(-0.15, value - 2.8 * density)
    elif last == ',':
        value = 0.23
    elif last == '.':
        before = prefix.token_strings[-3] if position > 1 else ''
        value = 0.08 if before and before[-1].isdigit() else 0.36
    elif last == ':':
        value = 0.65
    elif last == '=':
        value = 0.75
    elif last in '+-*/;<>':
        value = 0.56
    else:
        value = 0.43
    return history, value - 0.35 * density

"""Approximate a local quantity/intensity signal, not a full semantic parser.

Recognize amount expressions ('hundreds of', 'every single'), numerical suffixes
(decades, 100%, 30+), and East Asian approximate counts.  Productive superlatives,
ordinal-like endings and -ous/-oso/-eux adjective endings are another family.
Strengths are calibrated from training examples; ambiguous endings get weaker
responses.  Keep only a short causal text tail and reset it between documents.
Most other activations, including idiosyncratic small ones, are left at zero.
"""
import re

READS = ()

# Quantifiers are grouped by their ordinary meaning, not by token identity.
QUANTIFIERS = {
    'tens': 5.58, 'hundreds': 5.58,
    'thousands': 2.59,
    'millions': 1.39, 'billions': 1.39,
    'trillions': 1.39,
    'lots': 2.81, 'tons': 2.81, 'ton': 2.81,
    'loads': 2.81, 'heaps': 2.81,
    'dozens': 2.81, 'scores': 2.81,
    'full': 1.31,
    'lot': 0.35, 'plenty': 0.89, 'bunch': 0.89,
    'multitude': 0.89, 'plethora': 0.89,
    'handful': 0.89, 'myriad': 0.89, 'host': 0.89,
    'decades': 0.89, 'generations': 0.89,
}
FILLING = {'filled', 'packed', 'loaded', 'laden', 'flooded',
           'brimming', 'overflowing', 'teeming'}
INTENSITY_WORDS = {'numerous', 'massive', 'endless', 'countless',
                   'boundless', 'innumerable', 'enormous', 'immense',
                   'abundant', 'copious', 'tremendous'}


def predict(text, token):
    """Strength of a quantity or degree marker completed by this token."""
    t = token.lower()
    prev = re.search(r"([^\W\d_]+)$", text, re.UNICODE)
    word = prev[0].lower() if prev else ''
    if t.strip() == 'of':
        if word in ('number', 'numbers'):
            if re.search(r'\ba (?:large |good |fair )?number$', text.lower()):
                return 0.52
            return 0.0
        if word in ('amount', 'amounts', 'deal'):
            if re.search(r'(?:large|huge|great|considerable|substantial|vast) '
                         r'(?:amounts?|deal)$', text.lower()):
                return 0.56
            return 0.0
        return QUANTIFIERS.get(word, 0.0)
    if t == ' with' and word in FILLING:
        return 1.54
    if t == ' single' and word == 'every':
        return 6.57
    if t == ' and' and word == 'hundred':
        return 4.71
    if t.strip() in INTENSITY_WORDS:
        return 0.67
    if t == ' so' and word == 'or':
        return 1.52
    if t in ('+', '-plus', ' odd') and word in (
            'hundred', 'thousand', 'million', 'billion'):
        return 4.32

    if re.match(r'[数數几幾][十百千万萬亿億]', t):
        return 2.01
    if text.endswith(tuple('十百千万萬亿億')) and t.startswith(
            ('多', '余', '餘', '几', '幾')):
        return 7.5

    if text.endswith(('数', '數')) and t.startswith('多'):
        return 3.0
    if re.search(r'[0-9]+만$', text) and t == '여':
        return 5.9

    number = re.search(r'([0-9]+(?:\.[0-9]+)?)$', text)
    if number:
        n = number[0]
        round_number = n.endswith('0')
        if round_number and t in ('만', '대'):
            return 2.5
        if round_number and t.startswith(('来', '來')):
            return 7.5
        if t in (' odd', 'odd') and round_number:
            return 4.32
        if t in ('代', '后', '後') and round_number and len(n) == 2:
            return 3.29
        if token == ' s' and round_number:
            return 0.24
        if token in ('s', "'s", '’s') and round_number:
            if '.' in n:
                return 1.01
            return 2.97 if len(n) in (2, 4) else 1.04
        if t.strip() in ('%', 'percent'):
            if n == '100':
                return 2.45
            if round_number:
                return 0.06
        if t in ('+', '-plus'):
            if round_number:
                # In prose, '30+' means an open-ended quantity, not arithmetic.
                before = text[max(0, number.start()-25):number.start()]
                if re.search(r'[A-Za-z]{2,}[^=+*/]*$', before):
                    return 3.24
                return 0.38
            return 0.07
        if t.startswith(('多', '余', '餘', '几', '幾')):
            return 7.5 if round_number else 1.23
        if t == '年代' and round_number:
            return 2.44

    # The token must continue a word, rather than start a new one.
    if not t.isalpha() or not text or not text[-1].isalpha():
        return 0.0
    whole = word + t
    if re.search(r'issim(?:us|um|ae|is|orum|arum)$', whole):
        return 6.33
    if re.search(r'(?:iss|ís|íss)im[oaie]s?$', whole):
        if t in ('os', 'as', 'o', 'a', 's'):
            return 4.0
        return 8.68
    if t in ('sim', 'simo', 'sima') and word.endswith(('í', 'ís')):
        return 8.68
    if re.search(r'(?:ss|es|és|ót|ott|pés)im[oaie]s?$', whole):
        return 3.51
    if re.fullmatch(
            r'numer(?:ous|os[oaie]s?)|nombreu(?:x|se|ses)|inúmer[oa]s?', whole):
        return 6.04
    if (token == t and len(word) >= 3
            and re.search(r'os[oaie]s?$', whole) and t in (
            'oso', 'osa', 'osos', 'osas', 'ioso', 'iosa', 'iosos', 'iosas',
            'o', 'a', 'os', 'as', 'so', 'sa', 'ose', 'osi', 'se', 'si')):
        if t in ('ose', 'osi', 'se', 'si'):
            return 0.44
        return 2.17
    if (len(word) >= 4
            and t in ('ux', 'use', 'uses', 'euse', 'euses',
                      'reux', 'reuse', 'reuses')
            and re.search(r'eu(?:x|se|ses)$', whole)):
        return 2.17
    if t in ('ous', 'ious', 'inous'):
        return 0.57
    if t == 'less':
        return 4.62 if word in ('count', 'bound', 'end') else 0.31
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        text = ''
    else:
        text = carry[1]
    token = prefix.token_strings[-1]
    value = predict(text, token)
    return (doc, (text + token)[-100:]), value

"""Approximate the component's recurring spelling signal, not individual IDs.

Pieces ending in i or u are especially positive. Joined pieces are stronger
than space-prefixed words; common English spellings mostly weaken the effect.
Other vowel/consonant endings have much smaller values. Romanization extends
this rule beyond Latin, but Han characters stay at baseline. Tokens decoding
with replacement characters get a small positive fallback.

Document starts instead get a negative response: rarer English spellings
are more negative, with separate averages for digits and other token types.
This leaves token-specific and contextual variation unexplained.
"""
import re
from functools import lru_cache
import regex
from anyascii import anyascii
from wordfreq import zipf_frequency

READS = ()
HAN = regex.compile(r'\p{Script=Han}')
LATIN = regex.compile(r'\p{Script=Latin}')

# Columns: Latin base, other-script base, joined-piece gain,
# single-character gain, common-word slope, uppercase adjustment.
VOWEL_ENDINGS = {
    'a': ( .088, .061, .054, -.028, -.018, -.014),
    'e': (-.024, .014, .024, -.023,  .003, -.077),
    'i': ( .452, .227, .238,  .023, -.100, -.063),
    'o': ( .157, .095, .053, -.002, -.046, -.005),
    'u': ( .384,-.007, .104,  .141, -.121,  .013),
}


@lru_cache(maxsize=65536)
def spelling_value(text):
    s = text.strip()
    if not s:
        return -.01
    if s.startswith('<|'):
        return -.013
    if '\ufffd' in s:
        return .10
    if HAN.search(s):
        return -.02
    spelling = anyascii(s).lower()
    if not spelling or not spelling[-1].isalpha():
        return .002
    latin = bool(LATIN.search(s))
    match = re.search(r'([aeiou])([^aeiou]*)$', spelling)
    if not match:
        return -.03
    vowel, consonants = match.groups()
    joined = not text[0].isspace()
    if consonants:
        value = {'a': -.02, 'e': -.065, 'i': .02,
                 'o': .01, 'u': .045}[vowel]
        if joined:
            value += .03
        if len(consonants) > 1:
            value -= .04
        return value
    base, other, gain, single, common, upper = VOWEL_ENDINGS[vowel]
    value = base if latin else other
    if joined:
        value += gain
    if len(s) == 1:
        value += single
    if s.isascii() and s.isalpha():
        if not joined or len(s) > 2:
            value += common * max(0., zipf_frequency(s.lower(), 'en') - 4.)
        if s.isupper():
            value += upper
    if spelling.endswith('oo'):
        value += .315
    return value


def initial_value(text):
    s = text.strip()
    if not s:
        return -1.02
    if s.startswith('<|'):
        return -1.08
    if s.isdecimal():
        return -1.52
    if s.isascii() and s.isalpha():
        frequency = zipf_frequency(s.lower(), 'en')
        return max(-1.85, -.25 * (10.6 - frequency))
    return -.97 if s.isascii() else -1.59


def step(carry, prefix, upstream):
    first = prefix.position == 0 or (
        prefix.document_ids[-1] != prefix.document_ids[-2]
    )
    text = prefix.token_strings[-1]
    value = initial_value(text) if first else spelling_value(text)
    return None, float(value)

