"""Vowel-ending syllable detector, with a dip at each document start.

Plain-language summary of what this component responds to:
- The first token of every document (where a packed row starts a new document)
  pushes it strongly negative, about -1.2.
- Otherwise it is positive on short vowel pieces that end in i or u: a bare
  i or u (and look-alike letters such as Greek iota, Cyrillic и, u-umlaut),
  and romanised or foreign syllables such as "ri", "ari", "li", "Hu", "ui".
  The i-ending pieces are strongest (~0.8), u-endings (~0.55) and o-endings
  (~0.25) weaker. A leading space (the piece starts a new word) roughly halves
  these, so the signal is strongest inside a word.
- Whole words, digits, punctuation, newlines and most CJK characters are near 0.

The program reads only the current token's text, its leading space, and whether
it starts a document.
"""

READS = ()

# Full-strength for a bare vowel-like letter (not a syllable).
VOWEL_LETTERS = set("iuIUιиüíıίуúùû")

# Score for a piece by its last letter: inside a word (no leading space) and
# after a space (a new word).
INSIDE_WORD = {"i": 0.8, "u": 0.55, "o": 0.25}
NEW_WORD = {"i": 0.5, "u": 0.3, "o": 0.05}
SINGLE_INSIDE_WORD = {"i": 0.8, "u": 0.7, "o": 0.2}
SINGLE_NEW_WORD = {"i": 0.1, "u": 0.5, "o": 0.0}


def step(carry, prefix, upstream):
    if prefix.position == 0 or prefix.document_ids[-1] != prefix.document_ids[-2]:
        return None, -1.2
    text = prefix.token_strings[-1]
    lead = text.startswith(" ")
    core = text.lstrip()
    if len(core) == 1 and core in VOWEL_LETTERS:
        return None, 0.6
    if not (core.isascii() and core.isalpha()):
        return None, 0.0
    last = core[-1].lower()
    if len(core) == 1:
        # A lone letter: bare i/u fire, but " I" (the pronoun) and " i" barely do.
        if lead:
            return None, SINGLE_NEW_WORD.get(last, 0.0)
        return None, SINGLE_INSIDE_WORD.get(last, 0.0)
    table = NEW_WORD if lead else INSIDE_WORD
    return None, table.get(last, 0.0)

