"""A Greek-prose sigma detector, with a short echo on its continuation.

Mathematical sigma is mostly quiet: a Greek left neighbor or Greek-dominated
recent text is required. There are smaller, separate responses to a few Han roots
(cutting, sinking, tying), paired middle dots, and Cyrillic s followed by a.
Character counts fade exponentially. Split UTF-8 characters are joined before
counting scripts; all memory resets at document boundaries.
"""
import unicodedata
from codecs import utf_8_decode
from functools import lru_cache

READS = ()


@lru_cache(maxsize=4096)
def characters(text):
    greek = kana = visible = 0
    for ch in text:
        name = unicodedata.name(ch, '')
        greek += 'GREEK' in name and ch.isalpha()
        kana += 'HIRAGANA' in name or 'KATAKANA' in name
        visible += not ch.isspace()
    return greek, kana, visible


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        previous, greek, kana, visible, sigma_age = '', 0., 0., 0., 99
        pending = b''
        value = 0.18
    else:
        _, previous, greek, kana, visible, sigma_age, pending = carry
        value = 0.0
    raw = pending + prefix.token_bytes[-1]
    text, consumed = utf_8_decode(raw, 'replace', False)
    pending = raw[consumed:]
    word = text.strip()
    greek_prose = greek > 0.55 * visible and greek > 1
    if word in ('σ', 'Σ'):
        last_letter = ''.join(ch for ch in unicodedata.normalize('NFD', previous)
                              if not unicodedata.combining(ch))[-1:]
        greek_neighbor = ('GREEK' in unicodedata.name(last_letter, '')
                          if last_letter else False)
        greek_prose |= greek_neighbor and last_letter not in ('σ', 'Σ')
        if greek_prose:
            value = 6.3 if word == 'σ' else 2.7
            if previous.strip() == 'σ':
                value = 1.5
            elif (word == 'σ' and not text.startswith(' ')
                  and last_letter in ('ε', 'ω')):
                value = 4.5
            sigma_age = 0
    elif sigma_age == 1:
        vowel = unicodedata.normalize('NFD', word).lower()[:1]
        if vowel in ('ε', 'η', 'ο'):
            value = 3.3
        elif vowel in ('α', 'ι', 'ω', 'υ'):
            value = 1.3
        elif word == 'τ':
            value = 1.8 if previous.startswith(' ') else 0.4
    elif word == 'ς' and 2 <= sigma_age <= 4:
        value = {2: 2.6, 3: 1.2, 4: 0.3}[sigma_age]
    if word == '切':
        value = 1.5 if kana > 0.2 else 3.3
    elif word == '切实':
        value = 2.8
    elif word == '沉':
        value = 6.1
    elif word == '沈':
        value = 4.0
    elif word == '扎':
        value = 3.3
    elif word == 'а' and previous.strip().lower() == 'с':
        value = -1.8
    elif len(word) > 1 and set(word) == {'·'}:
        value = 1.6
    g, k, n = characters(text)
    carry = (doc, text, 0.85 * greek + g, 0.85 * kana + k,
             0.85 * visible + n, sigma_age + 1, pending)
    return carry, value

programs.haiku:
"""layers.1.mlp.down_proj:1341 -- a "Greek sigma" detector.

What it does: this component fires strongly on the lowercase Greek letter sigma (σ) when
it is written inside Greek text, e.g. the σ in προσωπο, μετάφρασ-η, κατά-στα. The
activation is about 6 there (range roughly 2 to 10) and near 0 elsewhere. The same
glyph used as a maths symbol (σ(x), "1 σ error", "σ = ...") does not fire.

Smaller effects, kept because they are cheap and real in the data:
  - final sigma ς in Greek text: weak (about 0.6);
  - a few Chinese characters that also fire (沉, 切, and its compounds): 2 to 7;
  - capital Sigma Σ inside Greek words: about 3.

Rule: Greek-context check = the last non-space character before the σ is a Greek letter.
"""
import unicodedata

READS = ()

SIGMA = {"σ", " σ"}
SIGMA_IN_GREEK = 6.0
OTHER = {"ς": 0.6, "Σ": 3.0, "沉": 7.0, "沈": 4.3, "切": 2.6, "切实": 2.8, "扎": 2.8, "契": 2.8}


def _is_greek_letter(ch):
    return ch.isalpha() and unicodedata.name(ch, "").startswith("GREEK")


def _after_greek_letter(text):
    """True if the last non-space character of `text` is a Greek letter."""
    stripped = text.rstrip(" �")
    return bool(stripped) and _is_greek_letter(stripped[-1])


def step(carry, prefix, upstream):
    t = prefix.position
    token = prefix.token_strings[t]
    value = 0.0
    same_doc = t > 0 and prefix.document_ids[t - 1] == prefix.document_ids[t]
    if token in SIGMA and same_doc and _after_greek_letter(prefix.text_prefixes[t - 1]):
        value = SIGMA_IN_GREEK
    elif token in OTHER:
        value = OTHER[token]
    return carry, float(value)

programs.sol:
"""A lexical approximation to an adverb/adverbial-ending signal.

English -ly word endings get graded responses: productive adjective endings,
uncommon words, and evaluative/evidential adverbs receive extra weight. A few
other languages' adverb endings and grammatical markers have separate rules.
Nominalizers get negative values; repeated interpuncts get a positive value.
This is not a syntactic parser. State is a short, document-local byte tail.
"""
import re
from functools import lru_cache
import wordnet
from wordfreq import zipf_frequency

READS = ()

EVALUATIVE = set('''
    fortunately unfortunately luckily unluckily happily sadly regrettably
    surprisingly unsurprisingly oddly strangely curiously amazingly wonderfully
    thankfully interestingly ironically importantly notably hopefully
    remarkably conveniently advantageously
'''.split())
EVIDENTIAL = set('''
    apparently evidently presumably seemingly supposedly allegedly ostensibly
    reportedly obviously undoubtedly
'''.split())
OTHER_DISCOURSE = set('likewise otherwise somehow anyhow anyway'.split())

# Common adjective-to-adverb formations, not token identities.
ENDINGS = (
    (('ably', 'ibly'), 0.39),
    (('ingly',), 1.49),
    (('edly',), 1.27),
    (('ously',), 0.24),
    (('fully',), 0.02),
    (('lessly',), 0.38),
    (('ishly',), 0.88),
)

@lru_cache(maxsize=32768)
def word_value(word):
    value = 0.0
    is_adverb = False
    if word.isascii() and word.endswith('ly'):
        pos = wordnet.parts_of_speech(word)
        stem = word[:-2]
        if word.endswith('ily'):
            stem = word[:-3] + 'y'
        productive = any(word.endswith(ends) for ends, _ in ENDINGS)
        is_adverb = ('adverb' in pos
                     or 'adjective' in wordnet.parts_of_speech(stem)
                     or (not pos and productive))
        if is_adverb:
            value = -0.06 + 0.17 * max(0., 5.5-zipf_frequency(word, 'en'))
            if 'adj.pert' in wordnet.categories(stem):
                value -= 0.28
            for ends, weight in ENDINGS:
                if word.endswith(ends):
                    value += weight
            if word in EVALUATIVE:
                value += 2.66
            if word in EVIDENTIAL:
                value += 1.33
            if word in {'accordingly', 'consequently'}:
                value += 1.26
    if word in OTHER_DISCOURSE:
        value += 0.09

    if len(word) > 6 and word.endswith('ment'):
        if zipf_frequency(word, 'fr') > max(2., zipf_frequency(word, 'en')+.5):
            value += 0.19
    if len(word) > 6 and word.endswith('mente'):
        value += 0.62
    if len(word) > 5 and word.endswith(('lich', 'weise', 'end', 'ende', 'enden')):
        if zipf_frequency(word, 'de') > max(2., zipf_frequency(word, 'en')+.5):
            if word.endswith('lich'):
                value += 0.53
            elif word.endswith('weise'):
                value += 0.55
            else:
                value += 0.84
    if word.endswith(('ясь', 'вшись')):
        value += 0.39
    if len(word) > 3 and word.endswith('но'):
        value += 0.12
    return value, is_adverb


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    tail = b'' if carry is None or carry[0] != doc else carry[1]
    raw = tail + prefix.token_bytes[-1]
    text = raw.decode('utf-8', errors='replace')
    token = prefix.token_strings[-1]
    match = re.search(r'([^\W\d_]+)\Z', text)
    word = match.group(1) if match else ''
    value, adverb = word_value(word.lower())
    if adverb:
        if len(token.strip()) < len(word):
            value += 0.34
        value = max(0., value)

    if token == '地':
        value += 0.41
    if token.endswith(('히', '하게')):
        value += 1.14
    if token in {'なお', 'ちなみに', 'やはり', 'やっぱり', 'もちろん',
                 '確かに', '恐らく'}:
        value += 0.81
    if token in {'当然', '显然', '无疑', '所述'}:
        value += 1.27
    if token in {'こと', 'ということ', ' 것'}:
        value -= 1.51
    if token and set(token) == {'·'} and len(token) > 1:
        value += 0.93
    if re.search(r'\b(no (doubt|wonder|problem)|of course|'
                 r'in (this way|any (case|event)))\Z', text, re.I):
        value += 0.86
    return (doc, raw[-192:]), float(value + 0.001)

"""Structured-value punctuation, rather than ordinary prose commas.

A comma ending a quoted value is strongest in a key/value object, especially
a JSON object's first "name" field. Braced and bracketed values and code-line
commas also respond. Empty values and prose commas respond much less.
Logical operators have the opposite sign. Only 200 recent characters are kept.
"""
import re

READS = ()


def predict(token, before):
    s = token.strip()
    if not s:
        return 0.0
    # Distances to recent structural punctuation describe the local syntax.
    distance = lambda c: len(before) - before.rfind(c) if c in before else 201
    colon, brace = distance(':'), distance('{')
    bracket, paren = distance('['), distance('(')
    colon_recent = colon < min(brace, bracket, paren, distance(';'))
    brace_recent = brace < min(bracket, paren, distance(';'))
    if s == '&&':
        return -0.7 if paren < 25 else -1.5
    if s in ('||', '??'):
        if not token.startswith(' '):
            return -0.15
        return -1.9 if colon < 185 else -0.65
    if s in ('===', '!==', '!='):
        return -0.6
    if s == '=>':
        quoted = before.rstrip().endswith(('"', "'"))
        return -1.1 if quoted and bracket < 60 else -0.12
    if any(c.isalnum() for c in s):
        return 0.0
    lines = token.count('\n')
    if ',' in s:
        ending, following = s.split(',', 1)
        leading_separator = token.startswith(' ') and not lines
        if leading_separator and not any(c in ending for c in '}])'):
            return 0.0
        if '}' in ending:
            if brace < 10:
                return 0.4
            return 3.1 if colon_recent else 1.8
        if ']' in ending:
            if lines:
                return 2.8
            return 2.4 if colon < 50 and brace < 100 else 0.5
        if ')' in ending:
            return 1.7 if lines == 1 else 0.05
        if '"' in ending or "'" in ending:
            if following.strip('\\'):
                return 0.4
            if colon_recent:
                if brace_recent:
                    first_name_field = re.search(
                        r'\{\s*"name"\s*:\s*"[^"\n]*$', before)
                    return 4.8 if first_name_field else 3.0
                return 2.6 if lines else 1.3
            if '\\' in token:
                return 2.4
            return 1.8 if lines == 1 else 0.45
        if lines > 1:
            return 0.05
        if lines == 1 or '\\' in token:
            if brace_recent:
                value_after_key = re.search(r':\s*[^,;{}\n]*$', before)
                return 2.8 if value_after_key else 1.3
            return 1.7 if re.search(r'\n[ \t]+[^\n]*$', before) else 0.35
        return 0.8 if colon < 8 else 0.02
    if '{' in s:
        if '"' in s and token.startswith(' '):
            return 2.1
        if before.rstrip().endswith(':'):
            return 0.5 if paren < 65 else 2.0
        return 0.05
    if '[' in s:
        if before.rstrip().endswith(':'):
            return 0.9 if brace < 190 else 0.2
        return 0.65 if lines == 1 and ',' in before[-80:] else 0.0
    if s in ('":', "':"):
        return -0.2
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    before = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    value = predict(token, before)
    return (doc, (before + token)[-200:]), float(value)

