"""layers.1.mlp.down_proj:1343 -- "the end of an item in a data literal".

This component fires on the punctuation that closes one entry of a structured,
data-like literal (JSON, a Python/JS dict or list, a multi-line table) and hands
over to the next entry. The strongest case is a JSON string value followed by a
comma, such as the `",` after `"name": "bash"` in a tool call, where the next
token is the next key (`"arguments"`). Its activation is:

  * high on a closing quote + comma (`",`, `',`, `\\",\\`) that ends a value of
    a JSON-style `"key": value` pair (about 2.5 more than a plain string item),
    more again inside a tool-call block;
  * moderate on a comma-newline inside a bracketed literal (`,\\n` between the
    lines of a multi-line dict or table);
  * moderate on a closing bracket with a comma (`},` `],\\n` `),`) after a
    JSON-style key, and on an opening `{"` or `{` after a key;
  * near zero in ordinary prose and in code (commas between function arguments,
    `&&`, `=>`, identifiers), and in the middle of a run of plain text.

The program tracks the bracket depth and the last ~60 characters of the current
document (reset at each document start), and reads only the current token.
"""
import re

READS = ()

QUOTE_COMMA = re.compile(r"""["'][\\]*,[\\]*\s*$""")    # ends a string, then a comma:  ",  ',  \",
BRACKET_COMMA = re.compile(r"""[)\]\}][\\]*,?[\\]*\s*$""")  # ends a bracket, then a comma:  ),  ],  },
NEWLINE_COMMA = re.compile(r",\\?n\s*$|,\n$")          # a comma and a line break
OPENER = re.compile(r"""[\[{]["']?$""")                # opens an object or list:  {"  [  {
KEY_VALUE = re.compile(r'"\s*:')                       # a JSON-style "key": just before


def step(carry, prefix, upstream):
    s = prefix.token_strings[-1]
    new_doc = len(prefix.document_ids) > 1 and prefix.document_ids[-1] != prefix.document_ids[-2]
    if carry is None or new_doc:
        carry = {"depth": 0, "recent": "", "tool": False}
    depth, recent, tool = carry["depth"], carry["recent"], carry["tool"]
    inside = depth > 0                           # within some (), [] or {}
    json = KEY_VALUE.search(recent) is not None  # a "key": just before
    if "tool_call" in s:
        tool = True                              # inside a tool-call block
    if QUOTE_COMMA.search(s):
        value = 1.0 + 0.4 * inside + 2.4 * json + 0.3 * tool
    elif BRACKET_COMMA.search(s):
        value = 0.4 * json
    elif NEWLINE_COMMA.search(s):
        value = 1.7 * inside
    elif OPENER.search(s):
        value = 1.9 * json
    elif s.strip() == ",":
        value = 0.6 * tool
    else:
        value = 0.0
    for ch in s:
        if ch in "([{":
            depth += 1
        elif ch in ")]}":
            depth = max(0, depth - 1)
    carry = {"depth": depth, "recent": (recent + s)[-60:], "tool": tool}
    return carry, float(value)
